-- Qula Plus baseline.
--
-- This one file builds the database as the live project had it on 12 November 2026, after the migration
-- 20261112101106_order_quantity_rules. It replaces the 85 migrations before it, which are kept for reference in
-- supabase/migrations_archive. Those files could not rebuild the database from empty: several patched functions by
-- matching their text, and four were applied to the live project without their SQL being recorded.
--
-- It was made from a database whose tables, columns, constraints, indexes, policies, triggers, grants, views, enums
-- and all 113 function bodies had the same fingerprints as the live project. The live project already has all of
-- this, so the file is never applied there. It carries the same version as the last migration it replaces, which
-- the live project records as applied.
--
-- Do not edit this file. Add new migrations after it.

create schema if not exists private;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists "uuid-ossp" with schema extensions;

-- Functions are created before the tables they read, so their bodies are not checked until they run.
set check_function_bodies = false;

--
--




--
-- Name: private; Type: SCHEMA; Schema: -; Owner: -
--



--
-- Name: public; Type: SCHEMA; Schema: -; Owner: -
--



--
-- Name: document_kind; Type: TYPE; Schema: public; Owner: -
--

CREATE TYPE public.document_kind AS ENUM (
    'invoice',
    'credit_note',
    'order',
    'requisition'
);


--
-- Name: document_status; Type: TYPE; Schema: public; Owner: -
--

CREATE TYPE public.document_status AS ENUM (
    'draft',
    'posted',
    'void',
    'open',
    'closed',
    'cancelled'
);


--
-- Name: e_document_direction; Type: TYPE; Schema: public; Owner: -
--

CREATE TYPE public.e_document_direction AS ENUM (
    'outbound',
    'inbound'
);


--
-- Name: e_document_status; Type: TYPE; Schema: public; Owner: -
--

CREATE TYPE public.e_document_status AS ENUM (
    'generated',
    'received',
    'invalid',
    'valid',
    'duplicate',
    'imported',
    'rejected'
);


--
-- Name: numbering_rule; Type: TYPE; Schema: public; Owner: -
--

CREATE TYPE public.numbering_rule AS ENUM (
    'on_insert',
    'on_post'
);


--
-- Name: apply_sales_document_defaults(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_sales_document_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_direction text;
  v_days integer;
  v_buyer text;
begin
  if tg_op = 'UPDATE' and old.status in ('posted', 'void') then
    return new;
  end if;

  select type into v_direction
  from public.transaction_types
  where id = new.transaction_type_id;

  if v_direction is distinct from 'Sales' or new.customer_id is null then
    return new;
  end if;

  select payment_terms_days, default_buyer_reference
    into v_days, v_buyer
  from public.customers
  where id = new.customer_id
    and organisation_id = new.organisation_id;

  if tg_op = 'INSERT' then
    if new.buyer_reference is null then
      new.buyer_reference := v_buyer;
    end if;
    if v_days is not null and new.due_date is null then
      new.due_date := new.transaction_date + v_days;
    end if;
    if v_days is not null and new.payment_terms is null then
      new.payment_terms := case
        when v_days = 0 then 'Due on receipt'
        when v_days = 1 then 'Payment due within 1 day'
        else 'Payment due within ' || v_days::text || ' days'
      end;
    end if;
    return new;
  end if;

  if v_days is not null
     and old.due_date is not distinct from (old.transaction_date + v_days)
     and (new.due_date is not distinct from old.due_date or new.due_date is null)
     and new.transaction_date is distinct from old.transaction_date then
    new.due_date := new.transaction_date + v_days;
  end if;

  return new;
end;
$$;


--
-- Name: begin_tenant_delete(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.begin_tenant_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform set_config('fintran.deleting_organisation', 'on', true);
  return old;
end;
$$;


--
-- Name: can_manage_tenant(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_manage_tenant(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.organisation_access
    where tenant_id = p_tenant_id
      and user_id = (select auth.uid())
      and role = 'owner'
  );
$$;


--
-- Name: canonical_json(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.canonical_json(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare v_type text; v_key text; v_item jsonb; v_parts text[] := array[]::text[]; v_num text;
begin
  if p_value is null then return 'null'; end if;
  v_type := jsonb_typeof(p_value);
  if v_type = 'null' then return 'null';
  elsif v_type = 'boolean' then return p_value::text;
  elsif v_type = 'number' then
    v_num := p_value #>> '{}';
    if position('.' in v_num) > 0 then v_num := regexp_replace(v_num, '0+$', ''); v_num := regexp_replace(v_num, '\.$', ''); end if;
    return v_num;
  elsif v_type = 'string' then return to_json(p_value #>> '{}')::text;
  elsif v_type = 'array' then
    for v_item in select value from jsonb_array_elements(p_value) loop v_parts := v_parts || private.canonical_json(v_item); end loop;
    return '[' || array_to_string(v_parts, ',') || ']';
  elsif v_type = 'object' then
    for v_key in select key from jsonb_object_keys(p_value) as key order by key loop
      v_parts := v_parts || (to_json(v_key)::text || ':' || private.canonical_json(p_value -> v_key));
    end loop;
    return '{' || array_to_string(v_parts, ',') || '}';
  end if;
  raise exception 'Unsupported JSON value';
end; $_$;


--
-- Name: check_e_document_content_hash(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.check_e_document_content_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare v_sha text; begin select sha256 into v_sha from public.e_documents where id = new.e_document_id; if v_sha is distinct from encode(extensions.digest(convert_to(new.xml, 'utf8'), 'sha256'), 'hex') then raise exception 'The e-document file does not match its recorded hash'; end if; return new; end; $$;


--
-- Name: create_organisation_defaults(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_organisation_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_code text := upper(btrim(coalesce(nullif(current_setting('fintran.home_currency', true), ''), 'EUR')));
  v_name text;
  v_currency uuid;
begin
  select name into v_name
  from public.ref_currencies
  where code = v_code
    and active;
  if v_name is null then
    raise exception 'Choose an active ISO currency';
  end if;

  insert into public.currencies (tenant_id, organisation_id, code, name, rate, iso_code)
  values (new.tenant_id, new.id, v_code, v_name, 1, v_code)
  returning id into v_currency;

  insert into public.organisation_defaults (organisation_id, tenant_id, home_currency_id)
  values (new.id, new.tenant_id, v_currency);
  return new;
end;
$$;


--
-- Name: document_period_locked(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.document_period_locked(p_organisation_id uuid, p_transaction_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.organisation_defaults
    where organisation_id = p_organisation_id
      and lock_date is not null
      and p_transaction_date <= lock_date
  );
$$;


--
-- Name: e_document_transition_allowed(public.e_document_direction, public.e_document_status, public.e_document_status); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.e_document_transition_allowed(p_direction public.e_document_direction, p_from public.e_document_status, p_to public.e_document_status) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_direction = 'outbound' and p_from = 'generated' and p_to in ('valid', 'invalid') then true
    when p_direction = 'inbound' and p_from = 'received' and p_to in ('valid', 'invalid', 'duplicate') then true
    when p_direction = 'inbound' and p_from = 'duplicate' and p_to in ('valid', 'rejected') then true
    when p_direction = 'inbound' and p_from = 'valid' and p_to in ('imported', 'rejected') then true
    when p_direction = 'inbound' and p_from = 'invalid' and p_to = 'rejected' then true
    else false
  end;
$$;


--
-- Name: einvoice_signature(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.einvoice_signature(p_key_id text, p_envelope jsonb) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_secret text; v_key bytea;
begin
  if p_key_id is null or p_key_id !~ '^[A-Za-z0-9_-]{1,40}$' then raise exception 'Unknown signing key'; end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'einvoice_hmac_' || p_key_id;
  if v_secret is null then raise exception 'Unknown signing key'; end if;
  v_key := decode(v_secret, 'base64');
  return encode(extensions.hmac(convert_to(private.canonical_json(p_envelope), 'utf8'), v_key, 'sha256'), 'hex');
end; $_$;


--
-- Name: enforce_business_terms(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_business_terms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and old.status in ('posted', 'void') then
    return new;
  end if;

  new.buyer_reference := nullif(btrim(new.buyer_reference), '');
  new.contract_reference := nullif(btrim(new.contract_reference), '');
  new.payment_terms := nullif(btrim(new.payment_terms), '');
  new.payment_means_code := nullif(upper(btrim(new.payment_means_code)), '');

  if new.buyer_reference is not null and char_length(new.buyer_reference) > 100 then
    raise exception 'Buyer reference can be up to 100 characters';
  end if;
  if new.contract_reference is not null and char_length(new.contract_reference) > 60 then
    raise exception 'Contract reference can be up to 60 characters';
  end if;
  if new.payment_terms is not null and char_length(new.payment_terms) > 400 then
    raise exception 'Payment terms can be up to 400 characters';
  end if;
  if (new.invoice_period_start is null) <> (new.invoice_period_end is null) then
    raise exception 'Enter both the invoice period start and end, or leave both blank';
  end if;
  if new.invoice_period_end < new.invoice_period_start then
    raise exception 'The invoice period end cannot be before the start';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_credited_line(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_credited_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind text;
  v_preceding uuid;
  v_credited record;
  v_already numeric;
begin
  if new.credited_line_id is null then
    if new.returns_to_order then
      raise exception 'Return to order needs the invoice line being credited';
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.credited_line_id is not distinct from old.credited_line_id
     and new.returns_to_order is not distinct from old.returns_to_order
     and new.quantity is not distinct from old.quantity then
    return new;
  end if;

  select kind.document_kind::text, header.preceding_header_id into v_kind, v_preceding
  from public.transaction_headers as header
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where header.id = new.header_id;
  if v_kind is distinct from 'credit_note' then
    raise exception 'Only a credit note line can credit an invoice line';
  end if;

  -- The invoice line is locked so two credit notes cannot both take the last of it.
  perform 1 from public.transaction_lines where id = new.credited_line_id for update;
  select line.quantity, line.line_number, line.header_id, line.organisation_id, line.source_line_id,
         kind.document_kind::text as kind
    into v_credited
  from public.transaction_lines as line
  join public.transaction_headers as header on header.id = line.header_id
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where line.id = new.credited_line_id;

  if v_credited.header_id is null or v_credited.organisation_id is distinct from new.organisation_id then
    raise exception 'The invoice line being credited was not found';
  end if;
  if v_credited.kind <> 'invoice' or v_preceding is null or v_credited.header_id is distinct from v_preceding then
    raise exception 'A credit note line can only credit a line on the invoice the credit note applies to';
  end if;
  if new.returns_to_order then
    if v_credited.source_line_id is null then
      raise exception 'Return to order is only for a line whose invoice line came from an order';
    end if;
    if coalesce(new.quantity, 0) <= 0 then
      raise exception 'A line marked Return to order needs a quantity';
    end if;
  end if;

  select coalesce(sum(credit.quantity), 0) into v_already
  from public.transaction_lines as credit
  join public.transaction_headers as header on header.id = credit.header_id
  where credit.credited_line_id = new.credited_line_id
    and credit.id is distinct from new.id
    and header.status in ('draft', 'posted');
  if v_already + coalesce(new.quantity, 0) > v_credited.quantity then
    raise exception 'This would credit more than was invoiced on line %. Invoiced %, already credited %, so % is left.',
      v_credited.line_number,
      private.plain_quantity(v_credited.quantity),
      private.plain_quantity(v_already),
      private.plain_quantity(greatest(v_credited.quantity - v_already, 0));
  end if;
  return new;
end;
$$;


--
-- Name: enforce_currency_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_currency_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  org_tenant uuid;
  v_iso text;
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id) then
    raise exception 'A currency cannot be moved to another organisation';
  end if;

  select tenant_id into org_tenant
  from public.organisations
  where id = new.organisation_id;

  if org_tenant is null or org_tenant is distinct from new.tenant_id then
    raise exception 'Organisation does not belong to this tenant';
  end if;

  new.code := upper(btrim(new.code));
  new.name := btrim(new.name);
  v_iso := upper(btrim(coalesce(new.iso_code, '')));
  if v_iso = '' then
    v_iso := new.code;
  end if;
  if not exists (select 1 from public.ref_currencies where code = v_iso) then
    raise exception 'Choose an ISO currency code';
  end if;
  new.iso_code := v_iso;

  if exists (
    select 1
    from public.organisation_defaults
    where home_currency_id = new.id
  ) and new.rate is distinct from 1 then
    raise exception 'The home currency rate must stay at 1';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_document_lines(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_document_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status public.document_status;
  v_date date;
  v_organisation uuid;
  v_kind text;
  v_order boolean;
  v_header uuid := case when tg_op = 'DELETE' then old.header_id else new.header_id end;
begin
  select header.status, header.transaction_date, header.organisation_id, kind.document_kind::text
    into v_status, v_date, v_organisation, v_kind
  from public.transaction_headers as header
  left join public.transaction_types as kind on kind.id = header.transaction_type_id
  where header.id = v_header;
  v_order := coalesce(v_kind in ('order', 'requisition'), false);

  if tg_op = 'DELETE' and v_status is null then
    return old;
  end if;

  if v_status in ('closed', 'cancelled') then
    raise exception 'Lines on a closed or cancelled order cannot be changed';
  end if;
  if v_status not in ('draft', 'open') then
    raise exception 'Lines on a posted or void document cannot be changed';
  end if;
  if not v_order and private.document_period_locked(v_organisation, v_date) then
    raise exception 'This date is in a locked period';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: enforce_document_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_document_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_allowed text[] := array[
    'paid_amount',
    'amount_due',
    'created_at', 'created_by', 'updated_at', 'updated_by'
  ];
  v_kind text;
  v_order boolean;
begin
  select document_kind::text into v_kind
  from public.transaction_types
  where id = case when tg_op = 'DELETE' then old.transaction_type_id else new.transaction_type_id end;
  v_order := coalesce(v_kind in ('order', 'requisition'), false);

  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      if v_order then
        raise exception 'Only a draft order can be deleted. Cancel it instead.';
      end if;
      raise exception 'Posted and void documents cannot be deleted';
    end if;
    if not v_order and private.document_period_locked(old.organisation_id, old.transaction_date) then
      raise exception 'This date is in a locked period';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.status is distinct from 'draft'
       or new.posted_at is not null
       or new.posted_by is not null
       or new.voided_at is not null
       or new.voided_by is not null
       or new.void_reason is not null then
      raise exception 'Document status can only be changed by posting or voiding';
    end if;
    if not v_order and private.document_period_locked(new.organisation_id, new.transaction_date) then
      raise exception 'This date is in a locked period';
    end if;
    return new;
  end if;

  if new.status is distinct from old.status
     or new.posted_at is distinct from old.posted_at
     or new.posted_by is distinct from old.posted_by
     or new.voided_at is distinct from old.voided_at
     or new.voided_by is distinct from old.voided_by
     or new.void_reason is distinct from old.void_reason then
    if current_setting('fintran.status_change', true) is distinct from 'on' then
      if v_order then
        raise exception 'An order status is changed with Activate, Close, Reopen or Cancel';
      end if;
      raise exception 'Document status can only be changed by posting or voiding';
    end if;
    if v_order then
      if new.status in ('posted', 'void') then
        raise exception 'An order is activated and closed. It is not posted.';
      end if;
      if new.posted_at is not null or new.posted_by is not null
         or new.voided_at is not null or new.voided_by is not null or new.void_reason is not null then
        raise exception 'That status change is not allowed';
      end if;
      if not (
        (old.status = 'draft' and new.status = 'open')
        or (old.status = 'open' and new.status in ('closed', 'cancelled'))
        or (old.status = 'closed' and new.status = 'open')
      ) then
        raise exception 'That status change is not allowed';
      end if;
    elsif not (
      (old.status = 'draft' and new.status = 'posted')
      or (old.status = 'posted' and new.status = 'void')
    ) then
      if new.status in ('open', 'closed', 'cancelled') then
        raise exception 'Only an order or a requisition can be activated and closed';
      end if;
      raise exception 'That status change is not allowed';
    end if;
  elsif old.status = 'posted' then
    v_old := to_jsonb(old) - v_allowed;
    v_new := to_jsonb(new) - v_allowed;
    if v_old is distinct from v_new then
      raise exception 'Only the paid amount can be changed on a posted document';
    end if;
  elsif old.status = 'void' then
    v_old := to_jsonb(old) - v_allowed;
    v_new := to_jsonb(new) - v_allowed;
    if v_old is distinct from v_new then
      raise exception 'A void document cannot be changed';
    end if;
  elsif old.status in ('closed', 'cancelled') then
    v_old := to_jsonb(old) - v_allowed;
    v_new := to_jsonb(new) - v_allowed;
    if v_old is distinct from v_new then
      if old.status = 'closed' then
        raise exception 'A closed order cannot be changed. Reopen it first.';
      end if;
      raise exception 'A cancelled order cannot be changed';
    end if;
  end if;

  if not v_order and (
    private.document_period_locked(new.organisation_id, new.transaction_date)
    or private.document_period_locked(old.organisation_id, old.transaction_date)
  ) then
    raise exception 'This date is in a locked period';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_e_invoice_totals(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_e_invoice_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_semantic jsonb;
  v_nett numeric;
  v_vat numeric;
  v_total numeric;
begin
  if tg_op <> 'UPDATE' or old.status is distinct from 'draft' or new.status is distinct from 'posted' then
    return new;
  end if;

  select semantic into v_semantic
  from public.e_documents
  where header_id = new.id
    and direction = 'inbound'
    and status = 'imported'
  order by created_at
  limit 1;

  if v_semantic is null then
    return new;
  end if;

  v_nett := nullif(v_semantic #>> '{BG-22,BT-109}', '')::numeric;
  v_vat := nullif(v_semantic #>> '{BG-22,BT-110}', '')::numeric;
  v_total := nullif(v_semantic #>> '{BG-22,BT-112}', '')::numeric;

  if new.foreign_nett_amount is distinct from v_nett
     or new.foreign_vat_amount is distinct from v_vat
     or new.foreign_total_amount is distinct from v_total then
    raise exception
      'Totals differ from the e-invoice (Qula Plus %, e-invoice %). Check the VAT rates and discounts.',
      trim_scale(new.foreign_total_amount),
      trim_scale(v_total);
  end if;
  return new;
end;
$$;


--
-- Name: enforce_home_currency(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_home_currency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_postal record;
  v_peppol record;
begin
  if tg_op = 'UPDATE' and new.organisation_id is distinct from old.organisation_id then
    raise exception 'Defaults cannot be moved to another organisation';
  end if;

  if new.home_currency_id is null then
    raise exception 'Choose a home currency';
  end if;

  if tg_op = 'UPDATE' and new.home_currency_id is distinct from old.home_currency_id then
    if exists (
      select 1
      from public.transaction_headers
      where organisation_id = new.organisation_id
    ) then
      raise exception 'The home currency cannot be changed once documents exist.';
    end if;
  end if;

  update public.currencies
  set rate = 1
  where id = new.home_currency_id
    and organisation_id = new.organisation_id
    and rate is distinct from 1;

  if not found and not exists (
    select 1
    from public.currencies
    where id = new.home_currency_id
      and organisation_id = new.organisation_id
  ) then
    raise exception 'Home currency must belong to this organisation';
  end if;

  select * into v_postal
  from private.prepare_postal(
    new.address_line1, new.address_line2, new.address_line3,
    new.city, new.post_code, new.county, new.country_code
  );
  new.address_line1 := v_postal.line1;
  new.address_line2 := v_postal.line2;
  new.address_line3 := v_postal.line3;
  new.city := v_postal.city;
  new.post_code := v_postal.post_code;
  new.county := v_postal.county;
  new.country_code := v_postal.country_code;

  new.contact_name := nullif(btrim(new.contact_name), '');
  new.contact_email := nullif(btrim(new.contact_email), '');
  new.website := nullif(btrim(new.website), '');
  new.phone := nullif(btrim(new.phone), '');
  new.vat_number := private.prepare_vat_number(new.vat_number);
  new.company_number := private.prepare_company_number(new.company_number);
  select * into v_peppol from private.prepare_peppol(new.peppol_scheme, new.peppol_id);
  new.peppol_scheme := v_peppol.scheme;
  new.peppol_id := v_peppol.identifier;
  new.iban := private.prepare_iban(new.iban);
  new.bic := private.prepare_bic(new.bic);
  new.bank_account_name := nullif(btrim(new.bank_account_name), '');
  if new.bank_account_name is not null and char_length(new.bank_account_name) > 100 then
    raise exception 'Account name can be up to 100 characters';
  end if;
  new.banking_details := nullif(btrim(new.banking_details), '');
  new.logo_path := nullif(btrim(new.logo_path), '');
  return new;
end;
$$;


--
-- Name: enforce_home_exchange_rate(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_home_exchange_rate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_home uuid;
begin
  select home_currency_id into v_home from public.organisation_defaults where organisation_id = new.organisation_id;
  if v_home is not null and new.currency_id = v_home and new.exchange_rate is distinct from 1 then
    raise exception 'The home currency exchange rate must be 1';
  end if;
  return new;
end; $$;


--
-- Name: enforce_line_unit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_line_unit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_direction text;
begin
  new.unit_code := upper(btrim(coalesce(new.unit_code, '')));
  if new.unit_code = '' then
    new.unit_code := 'C62';
  end if;

  new.line_note := nullif(btrim(new.line_note), '');
  if new.line_note is not null and char_length(new.line_note) > 400 then
    raise exception 'A line note can be up to 400 characters';
  end if;

  new.seller_item_id := nullif(btrim(new.seller_item_id), '');
  if new.seller_item_id is not null and char_length(new.seller_item_id) > 60 then
    raise exception 'A seller item identifier can be up to 60 characters';
  end if;

  if new.seller_item_id is not null then
    select type into v_direction
    from public.transaction_types
    where id = new.transaction_type_id;

    if v_direction = 'Sales' then
      raise exception 'A seller item identifier is only stored on a purchase';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_organisation_tenant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_organisation_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.organisations
    where id = new.organisation_id
      and tenant_id = new.tenant_id
  ) then
    raise exception 'Organisation does not belong to this tenant';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_party_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_party_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  org_tenant uuid;
  v_postal record;
  v_peppol record;
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id) then
    raise exception 'A record cannot be moved to another organisation';
  end if;

  select tenant_id into org_tenant
  from public.organisations
  where id = new.organisation_id;

  if org_tenant is null or org_tenant is distinct from new.tenant_id then
    raise exception 'Organisation does not belong to this tenant';
  end if;

  new.code := upper(btrim(new.code));
  new.name := btrim(new.name);
  new.phone := nullif(btrim(new.phone), '');
  new.email := nullif(btrim(new.email), '');
  new.website := nullif(btrim(new.website), '');
  new.contact_details := nullif(btrim(new.contact_details), '');
  new.notes := nullif(btrim(new.notes), '');

  select * into v_postal
  from private.prepare_postal(
    new.address_line1, new.address_line2, new.address_line3,
    new.city, new.post_code, new.county, new.country_code
  );
  new.address_line1 := v_postal.line1;
  new.address_line2 := v_postal.line2;
  new.address_line3 := v_postal.line3;
  new.city := v_postal.city;
  new.post_code := v_postal.post_code;
  new.county := v_postal.county;
  new.country_code := v_postal.country_code;
  new.vat_number := private.prepare_vat_number(new.vat_number);
  new.company_number := private.prepare_company_number(new.company_number);
  select * into v_peppol from private.prepare_peppol(new.peppol_scheme, new.peppol_id);
  new.peppol_scheme := v_peppol.scheme;
  new.peppol_id := v_peppol.identifier;
  return new;
end;
$$;


--
-- Name: enforce_preceding_invoice(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_preceding_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind public.document_kind;
  v_direction text;
  v_target_status public.document_status;
  v_target_kind public.document_kind;
  v_target_direction text;
  v_target_supplier uuid;
  v_target_customer uuid;
  v_target_reference integer;
  v_target_number text;
  v_target_date date;
  v_found boolean;
begin
  if tg_op = 'UPDATE' and old.status in ('posted', 'void') then
    return new;
  end if;

  new.preceding_reference := nullif(btrim(new.preceding_reference), '');
  if new.preceding_reference is not null and char_length(new.preceding_reference) > 60 then
    raise exception 'The credited invoice reference can be up to 60 characters';
  end if;

  if new.preceding_header_id is not null then
    if new.preceding_header_id = new.id then
      raise exception 'A document cannot credit itself';
    end if;

    select
      header.status,
      header.supplier_id,
      header.customer_id,
      header.reference,
      header.document_number,
      header.transaction_date,
      kind.document_kind,
      kind.type
    into
      v_target_status,
      v_target_supplier,
      v_target_customer,
      v_target_reference,
      v_target_number,
      v_target_date,
      v_target_kind,
      v_target_direction
    from public.transaction_headers as header
    join public.transaction_types as kind on kind.id = header.transaction_type_id
    where header.id = new.preceding_header_id
      and header.organisation_id = new.organisation_id;

    v_found := found;

    if v_found then
      if v_target_status is distinct from 'posted' or v_target_kind is distinct from 'invoice' then
        raise exception 'The credited document must be a posted invoice';
      end if;

      select document_kind, type into v_kind, v_direction
      from public.transaction_types
      where id = new.transaction_type_id;

      if v_target_direction is distinct from v_direction then
        raise exception 'Choose a posted invoice from this organisation';
      end if;

      if v_direction = 'Purchases' and v_target_supplier is distinct from new.supplier_id then
        raise exception 'The credited document must be for the same supplier';
      end if;

      if v_direction = 'Sales' and v_target_customer is distinct from new.customer_id then
        raise exception 'The credited document must be for the same customer';
      end if;

      if new.preceding_reference is null then
        new.preceding_reference := coalesce(v_target_number, v_target_reference::text);
      end if;
      if new.preceding_date is null then
        new.preceding_date := v_target_date;
      end if;
    end if;
  end if;

  if tg_op = 'UPDATE'
     and old.status is distinct from 'posted'
     and new.status = 'posted' then
    select document_kind into v_kind
    from public.transaction_types
    where id = new.transaction_type_id;

    if v_kind = 'credit_note' and new.preceding_reference is null then
      raise exception 'Enter the invoice this credit note applies to';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_product(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_product() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  org_tenant uuid;
  gl_type text;
  vat_kind text;
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id) then
    raise exception 'A product cannot be moved to another organisation';
  end if;

  select tenant_id into org_tenant
  from public.organisations
  where id = new.organisation_id;

  if org_tenant is null or org_tenant is distinct from new.tenant_id then
    raise exception 'Organisation does not belong to this tenant';
  end if;

  new.code := upper(btrim(new.code));
  new.description := btrim(new.description);

  select account_type into gl_type from public.gl_codes where id = new.purchase_gl_code_id;
  if gl_type is distinct from 'Expense' then
    raise exception 'Purchase GL code must be an Expense account';
  end if;

  select account_type into gl_type from public.gl_codes where id = new.sales_gl_code_id;
  if gl_type is distinct from 'Income' then
    raise exception 'Sales GL code must be an Income account';
  end if;

  select vat_type into vat_kind from public.vat_rates where id = new.purchase_vat_code_id;
  if vat_kind is distinct from 'Expense' then
    raise exception 'Purchase VAT code must be an Expense rate';
  end if;

  select vat_type into vat_kind from public.vat_rates where id = new.sales_vat_code_id;
  if vat_kind is distinct from 'Sales' then
    raise exception 'Sales VAT code must be a Sales rate';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_product_unit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_product_unit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.unit_code := upper(btrim(coalesce(new.unit_code, '')));
  if new.unit_code = '' then
    new.unit_code := 'C62';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_reference_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_reference_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  org_tenant uuid;
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id) then
    raise exception 'A code cannot be moved to another organisation';
  end if;

  select tenant_id into org_tenant
  from public.organisations
  where id = new.organisation_id;

  if org_tenant is null or org_tenant is distinct from new.tenant_id then
    raise exception 'Organisation does not belong to this tenant';
  end if;

  new.code := upper(btrim(new.code));
  new.description := btrim(new.description);
  return new;
end;
$$;


--
-- Name: enforce_requisition_type(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_requisition_type() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.document_kind::text = 'requisition' and new.type is distinct from 'Purchases' then
    raise exception 'A requisition is a Purchases document';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_sales_posting(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_sales_posting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_direction text;
  v_kind text;
  v_invoice_total numeric;
  v_invoice_currency uuid;
  v_credited numeric;
begin
  if tg_op <> 'UPDATE' or old.status is distinct from 'draft' or new.status is distinct from 'posted' then
    return new;
  end if;

  select type, document_kind::text into v_direction, v_kind
  from public.transaction_types
  where id = new.transaction_type_id;

  if v_direction = 'Sales' and new.transaction_date > current_date + 1 then
    raise exception 'The document date cannot be more than one day in the future';
  end if;

  if v_direction = 'Sales' and exists (
    select 1
    from public.transaction_lines as line
    left join public.gl_codes as gl on gl.id = line.gl_code_id
    where line.header_id = new.id
      and (line.gl_code_id is null or gl.account_type is distinct from 'Income')
  ) then
    raise exception 'Each sales line needs an Income GL code';
  end if;

  if v_kind = 'credit_note' and new.preceding_header_id is not null then
    select foreign_total_amount, currency_id
      into v_invoice_total, v_invoice_currency
    from public.transaction_headers
    where id = new.preceding_header_id
      and organisation_id = new.organisation_id
    for update;

    if v_invoice_currency is distinct from new.currency_id then
      raise exception 'The credited document must use the same currency';
    end if;

    select coalesce(sum(credit.foreign_total_amount), 0) into v_credited
    from public.transaction_headers as credit
    join public.transaction_types as kind on kind.id = credit.transaction_type_id
    where credit.preceding_header_id = new.preceding_header_id
      and credit.status = 'posted'
      and credit.id is distinct from new.id
      and kind.document_kind = 'credit_note';

    if v_credited + new.foreign_total_amount > v_invoice_total then
      raise exception 'This credit note would take total credits above the original invoice total.';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_source_line(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_source_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind text;
  v_direction text;
  v_party uuid;
  v_organisation uuid;
  v_used numeric;
  v_source record;
begin
  -- This line as a source: an order line cannot drop below what is already invoiced from it.
  if exists (select 1 from public.transaction_lines as drawn where drawn.source_line_id = new.id) then
    select kind.document_kind::text into v_kind
    from public.transaction_headers as header
    join public.transaction_types as kind on kind.id = header.transaction_type_id
    where header.id = new.header_id;
    if v_kind = 'order' then
      v_used := private.order_line_used(new.id, null);
      if v_used > new.quantity then
        raise exception 'Line % already has % invoiced. Its quantity cannot be less than that.',
          new.line_number, private.plain_quantity(v_used);
      end if;
    end if;
  end if;

  -- This line as a target.
  if new.source_line_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.source_line_id is not distinct from old.source_line_id
     and new.quantity is not distinct from old.quantity then
    return new;
  end if;
  if new.source_line_id = new.id then
    raise exception 'A line cannot come from itself';
  end if;

  select header.organisation_id, kind.document_kind::text, kind.type, coalesce(header.supplier_id, header.customer_id)
    into v_organisation, v_kind, v_direction, v_party
  from public.transaction_headers as header
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where header.id = new.header_id;

  -- The source line is locked so two invoices cannot both take the last of it.
  perform 1 from public.transaction_lines where id = new.source_line_id for update;
  select line.quantity, line.organisation_id, header.status::text as status, kind.document_kind::text as kind,
         kind.type as direction, coalesce(header.supplier_id, header.customer_id) as party, header.document_number
    into v_source
  from public.transaction_lines as line
  join public.transaction_headers as header on header.id = line.header_id
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where line.id = new.source_line_id;

  if v_source.quantity is null or v_source.organisation_id is distinct from v_organisation then
    raise exception 'The order line this came from was not found';
  end if;
  if not ((v_source.kind = 'order' and v_kind = 'invoice') or (v_source.kind = 'requisition' and v_kind = 'order')) then
    raise exception 'An invoice line comes from an order, and an order line comes from a requisition';
  end if;
  if v_source.direction is distinct from v_direction then
    raise exception 'The two documents must both be purchases or both be sales';
  end if;
  if v_source.status not in ('open', 'closed') then
    raise exception 'The order must be active before it is invoiced';
  end if;

  if v_source.kind = 'order' then
    if v_source.party is distinct from v_party then
      raise exception 'The invoice must be for the same supplier or customer as the order';
    end if;
    v_used := private.order_line_used(new.source_line_id, new.id);
    if v_used + new.quantity > v_source.quantity then
      raise exception 'This would invoice more than was ordered on %. Ordered %, already invoiced %, so % is left.',
        coalesce(v_source.document_number, 'the order'),
        private.plain_quantity(v_source.quantity),
        private.plain_quantity(v_used),
        private.plain_quantity(greatest(v_source.quantity - v_used, 0));
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_transaction_form(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_transaction_form() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_type text;
  v_kind text;
  v_flex text[];
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id
       or new.transaction_type_id is distinct from old.transaction_type_id) then
    raise exception 'A form cannot be moved to another transaction type';
  end if;

  select type, document_kind::text, array[flex1_label, flex2_label, flex3_label, flex4_label, flex5_label]
    into v_type, v_kind, v_flex
  from public.transaction_types
  where id = new.transaction_type_id;

  if v_type is null then
    raise exception 'Transaction type must belong to this organisation';
  end if;

  perform private.validate_form_layout(new.layout, v_type, v_kind);

  if new.layout->'headerFields' ? 'flex1' and v_flex[1] is null
     or new.layout->'headerFields' ? 'flex2' and v_flex[2] is null
     or new.layout->'headerFields' ? 'flex3' and v_flex[3] is null
     or new.layout->'headerFields' ? 'flex4' and v_flex[4] is null
     or new.layout->'headerFields' ? 'flex5' and v_flex[5] is null then
    raise exception 'A flex field is on the form, but this transaction type has no label for it';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_transaction_header(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_transaction_header() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  org_tenant uuid;
  type_kind text;
  v_numbering public.numbering_rule;
  v_prefix text;
  v_padding integer;
  v_party_currency uuid;
  nett numeric(16, 4);
  vat numeric(16, 4);
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id
       or new.transaction_type_id is distinct from old.transaction_type_id) then
    raise exception 'A transaction cannot be moved or renumbered';
  end if;

  if tg_op = 'UPDATE' and new.reference is distinct from old.reference then
    if old.reference is not null
       or current_setting('fintran.status_change', true) is distinct from 'on' then
      raise exception 'A transaction cannot be moved or renumbered';
    end if;
  end if;

  select tenant_id into org_tenant
  from public.organisations
  where id = new.organisation_id;

  if org_tenant is null or org_tenant is distinct from new.tenant_id then
    raise exception 'Organisation does not belong to this tenant';
  end if;

  select type, numbering
    into type_kind, v_numbering
  from public.transaction_types
  where id = new.transaction_type_id;

  if type_kind = 'Sales' then
    if new.customer_id is null then
      raise exception 'Choose a customer';
    end if;
    if new.supplier_id is not null then
      raise exception 'A sales document cannot have a supplier';
    end if;
  elsif type_kind = 'Purchases' then
    if new.supplier_id is null then
      raise exception 'Choose a supplier';
    end if;
    if new.customer_id is not null then
      raise exception 'A purchase document cannot have a customer';
    end if;
  else
    raise exception 'Choose a Purchases transaction type';
  end if;

  if new.exchange_rate is null or new.exchange_rate <= 0 then
    raise exception 'Enter an exchange rate greater than 0';
  end if;

  new.party_name := btrim(new.party_name);
  new.contact_details := nullif(btrim(new.contact_details), '');
  new.notes := nullif(btrim(new.notes), '');
  new.order_number := nullif(btrim(new.order_number), '');
  new.supplier_reference := nullif(btrim(new.supplier_reference), '');
  new.flex1 := nullif(btrim(new.flex1), '');
  new.flex2 := nullif(btrim(new.flex2), '');
  new.flex3 := nullif(btrim(new.flex3), '');
  new.flex4 := nullif(btrim(new.flex4), '');
  new.flex5 := nullif(btrim(new.flex5), '');
  if new.rounding_amount is null then
    new.rounding_amount := 0;
  end if;

  if type_kind = 'Sales' and new.supplier_reference is not null then
    raise exception 'A supplier invoice number is only stored on a purchase';
  end if;

  if type_kind = 'Sales' then
    select currency_id into v_party_currency
    from public.customers
    where id = new.customer_id
      and organisation_id = new.organisation_id;
  else
    select currency_id into v_party_currency
    from public.suppliers
    where id = new.supplier_id
      and organisation_id = new.organisation_id;
  end if;
  if v_party_currency is null or v_party_currency is distinct from new.currency_id then
    raise exception 'The document currency must match the party currency';
  end if;

  if tg_op = 'INSERT' and v_numbering is distinct from 'on_post' then
    new.reference := private.issue_reference(new.transaction_type_id);
  elsif tg_op = 'INSERT' then
    new.reference := null;
  end if;

  if tg_op = 'UPDATE' and old.document_number is not null then
    new.document_number := old.document_number;
  elsif new.reference is not null then
    select reference_prefix, reference_padding into v_prefix, v_padding
    from public.transaction_types
    where id = new.transaction_type_id;
    new.document_number := private.format_document_number(v_prefix, v_padding, new.reference);
    if char_length(new.document_number) > 30 or char_length(new.document_number) < 1 then
      raise exception 'The document number is too long';
    end if;
  end if;

  if tg_op = 'UPDATE' and old.status in ('posted', 'void') then
    new.foreign_nett_amount := old.foreign_nett_amount;
    new.foreign_vat_amount := old.foreign_vat_amount;
    new.foreign_total_amount := old.foreign_total_amount;
    new.home_nett_amount := old.home_nett_amount;
    new.home_vat_amount := old.home_vat_amount;
    new.home_total_amount := old.home_total_amount;
    new.rounding_amount := old.rounding_amount;
    new.amount_due := round(old.foreign_total_amount - coalesce(new.paid_amount, 0) + old.rounding_amount, 2);
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status = 'draft' and new.status = 'posted' then
    if type_kind = 'Sales' and exists (
      select 1 from public.transaction_lines
      where header_id = new.id and vat_rate_id is null
    ) then
      raise exception 'Enter a VAT code on every line';
    end if;
    if exists (
      select 1
      from public.transaction_lines
      where header_id = new.id
      group by vat_category, vat_percentage
      having count(distinct coalesce(exemption_code, '') || '|' || coalesce(exemption_reason, '')) > 1
    ) then
      raise exception 'Lines with the same VAT category and rate must use the same exemption';
    end if;
  end if;

  select coalesce(sum(grouped.taxable), 0), coalesce(sum(grouped.vat), 0)
    into nett, vat
  from (
    select
      round(sum(nett_amount), 2) as taxable,
      round(round(sum(nett_amount), 2) * vat_percentage / 100, 2) as vat
    from public.transaction_lines
    where header_id = new.id
    group by vat_category, vat_percentage
  ) as grouped;

  new.foreign_nett_amount := nett;
  new.foreign_vat_amount := vat;
  new.foreign_total_amount := nett + vat;
  new.home_nett_amount := round(nett / new.exchange_rate, 2);
  new.home_vat_amount := round(vat / new.exchange_rate, 2);
  new.home_total_amount := round((nett + vat) / new.exchange_rate, 2);
  new.amount_due := round(nett + vat - coalesce(new.paid_amount, 0) + new.rounding_amount, 2);
  return new;
end;
$$;


--
-- Name: enforce_transaction_line(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_transaction_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  header_org uuid;
  header_tenant uuid;
  header_type uuid;
  vat_kind text;
  vat_rate numeric(5, 2);
  v_category text;
  v_exemption_code text;
  v_exemption_reason text;
  v_direction text;
  copy_rate boolean;
begin
  select organisation_id, tenant_id, transaction_type_id
    into header_org, header_tenant, header_type
  from public.transaction_headers
  where id = new.header_id;
  if header_org is null then
    raise exception 'Choose a transaction';
  end if;
  new.organisation_id := header_org;
  new.tenant_id := header_tenant;
  new.transaction_type_id := header_type;
  new.description := btrim(new.description);
  if new.discount_amount > new.quantity * new.price then
    raise exception 'Discount cannot be more than quantity times price';
  end if;
  new.nett_amount := round(new.quantity * new.price - new.discount_amount, 2);
  copy_rate := tg_op = 'INSERT' or new.vat_rate_id is distinct from old.vat_rate_id;
  select type into v_direction from public.transaction_types where id = new.transaction_type_id;
  if new.vat_rate_id is null then
    new.vat_percentage := 0;
    new.vat_category := 'O';
    new.exemption_code := null;
    new.exemption_reason := null;
  elsif copy_rate then
    select vat_type, rate, vat_rates.vat_category, exemption_code, exemption_reason
      into vat_kind, vat_rate, v_category, v_exemption_code, v_exemption_reason
    from public.vat_rates where id = new.vat_rate_id;
    if v_direction = 'Sales' and vat_kind is distinct from 'Sales' then
      raise exception 'Sales VAT code must be a Sales rate';
    end if;
    if v_direction is distinct from 'Sales' and vat_kind is distinct from 'Expense' then
      raise exception 'Purchase VAT code must be an Expense rate';
    end if;
    new.vat_percentage := vat_rate;
    new.vat_category := v_category;
    new.exemption_code := v_exemption_code;
    new.exemption_reason := v_exemption_reason;
  else
    select vat_type into vat_kind from public.vat_rates where id = new.vat_rate_id;
    if v_direction = 'Sales' and vat_kind is distinct from 'Sales' then
      raise exception 'Sales VAT code must be a Sales rate';
    end if;
    if v_direction is distinct from 'Sales' and vat_kind is distinct from 'Expense' then
      raise exception 'Purchase VAT code must be an Expense rate';
    end if;
  end if;
  new.vat_amount := round(new.nett_amount * new.vat_percentage / 100, 2);
  return new;
end;
$$;


--
-- Name: enforce_transaction_type(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_transaction_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  org_tenant uuid;
  v_documents integer;
  v_layout jsonb;
begin
  if tg_op = 'UPDATE'
     and (new.tenant_id is distinct from old.tenant_id
       or new.organisation_id is distinct from old.organisation_id) then
    raise exception 'A transaction type cannot be moved to another organisation';
  end if;

  select tenant_id into org_tenant
  from public.organisations
  where id = new.organisation_id;

  if org_tenant is null or org_tenant is distinct from new.tenant_id then
    raise exception 'Organisation does not belong to this tenant';
  end if;

  new.code := upper(btrim(new.code));
  new.description := btrim(new.description);
  new.flex1_label := nullif(btrim(new.flex1_label), '');
  new.flex2_label := nullif(btrim(new.flex2_label), '');
  new.flex3_label := nullif(btrim(new.flex3_label), '');
  new.flex4_label := nullif(btrim(new.flex4_label), '');
  new.flex5_label := nullif(btrim(new.flex5_label), '');
  new.reference_prefix := nullif(btrim(new.reference_prefix), '');

  if new.reference_prefix is not null and new.reference_prefix !~ '^[A-Za-z0-9./-]{1,10}$' then
    raise exception 'A reference prefix can use letters, digits, and - / . and must be at most 10 characters';
  end if;
  if new.reference_padding is null or new.reference_padding < 0 or new.reference_padding > 10 then
    raise exception 'Reference padding must be from 0 to 10';
  end if;

  if new.type = 'Sales' then
    new.numbering := 'on_post';
  end if;

  if tg_op = 'UPDATE'
     and (new.numbering is distinct from old.numbering
       or new.type is distinct from old.type
       or new.document_kind is distinct from old.document_kind) then
    select count(*) into v_documents
    from public.transaction_headers
    where transaction_type_id = new.id;

    if v_documents > 0 and new.numbering is distinct from old.numbering then
      raise exception 'Numbering cannot change after a document has been entered';
    end if;
    if v_documents > 0 and new.type is distinct from old.type then
      raise exception 'The transaction type cannot change after a document has been entered';
    end if;
    if v_documents > 0 and new.document_kind is distinct from old.document_kind then
      raise exception 'The document kind cannot change after a document has been entered';
    end if;
  end if;

  if tg_op = 'UPDATE'
     and new.type = 'Sales'
     and (
       old.type is distinct from 'Sales'
       or (new.document_kind = 'credit_note' and old.document_kind is distinct from 'credit_note')
     ) then
    select layout into v_layout
    from public.transaction_forms
    where transaction_type_id = new.id;
    if v_layout is not null then
      perform private.validate_form_layout(v_layout, 'Sales', new.document_kind::text);
    end if;
  end if;

  if tg_op = 'INSERT' then
    new.last_reference := 0;
  elsif new.last_reference is distinct from old.last_reference
    and new.last_reference is distinct from old.last_reference + 1 then
    new.last_reference := old.last_reference;
  end if;

  return new;
end;
$_$;


--
-- Name: enforce_vat_category(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_vat_category() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_zero boolean;
  v_reason boolean;
begin
  new.exemption_reason := nullif(btrim(new.exemption_reason), '');
  new.exemption_code := nullif(btrim(new.exemption_code), '');

  select rate_must_be_zero, requires_exemption_reason
    into v_zero, v_reason
  from public.ref_vat_categories
  where code = new.vat_category;

  if v_zero is null then
    raise exception 'Choose a VAT category';
  end if;
  if new.vat_category = 'S' and new.rate <= 0 then
    raise exception 'A standard rate VAT code must be above zero';
  end if;
  if v_zero and new.rate <> 0 then
    raise exception 'This VAT category must have a rate of zero';
  end if;
  if v_reason and new.exemption_code is null and new.exemption_reason is null then
    raise exception 'Enter an exemption code or a reason';
  end if;
  return new;
end;
$$;


--
-- Name: finish_tenant_delete(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finish_tenant_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform set_config('fintran.deleting_organisation', 'off', true);
  return old;
end;
$$;


--
-- Name: format_document_number(text, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.format_document_number(p_prefix text, p_padding integer, p_reference integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_prefix, '') || lpad(
    p_reference::text,
    greatest(p_padding, char_length(p_reference::text)),
    '0'
  );
$$;


--
-- Name: freeze_e_document_content(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.freeze_e_document_content() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin raise exception 'An e-document file cannot be changed'; end; $$;


--
-- Name: freeze_e_document_events(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.freeze_e_document_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin raise exception 'E-document history cannot be changed'; end; $$;


--
-- Name: guard_access_point_settings(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_access_point_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.environment = 'production' and not exists (
    select 1 from public.organisation_defaults
    where organisation_id = new.organisation_id and nullif(btrim(peppol_id), '') is not null
  ) then
    raise exception 'Add a Peppol ID before using production';
  end if;
  if tg_op = 'UPDATE'
     and old.participant_registered
     and new.provider_code is distinct from old.provider_code then
    raise exception 'Deregister the Peppol ID with the current provider before switching.';
  end if;
  if new.config->>'baseUrl' is not null and new.config->>'baseUrl' <> '' and new.config->>'baseUrl' not like 'https://%' then
    raise exception 'The base URL must use https';
  end if;
  return new;
end;
$$;


--
-- Name: guard_ai_actions_enabled(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_ai_actions_enabled() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not new.enabled then
    new.actions_enabled := false;
  end if;
  return new;
end;
$$;


--
-- Name: guard_ai_log_answers(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_ai_log_answers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_needs_notice boolean;
  v_accepted_now boolean;
begin
  if not new.log_answers then
    return new;
  end if;
  if tg_op = 'INSERT' then
    v_needs_notice := true;
    v_accepted_now := new.log_notice_accepted_at is not null;
  else
    v_needs_notice := not old.log_answers or new.answer_retention_days is distinct from old.answer_retention_days;
    v_accepted_now := new.log_notice_accepted_at is not null
      and new.log_notice_accepted_at is distinct from old.log_notice_accepted_at;
  end if;
  if v_needs_notice and not v_accepted_now then
    raise exception 'Accept the notice that questions and answers will be stored for % days and are visible to owners and admins',
      new.answer_retention_days;
  end if;
  if v_accepted_now then
    new.log_notice_accepted_by := auth.uid();
  end if;
  return new;
end;
$$;


--
-- Name: guard_ai_settings(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_ai_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.data_notice_accepted_at is not null and new.data_notice_accepted_by is null then
    new.data_notice_accepted_by := auth.uid();
  end if;
  if new.enabled then
    if new.provider_code is null or nullif(btrim(new.model), '') is null or new.data_notice_accepted_at is null then
      raise exception 'Choose a provider and model, and accept the data notice';
    end if;
    if not exists (
      select 1 from public.organisation_secrets
      where organisation_id = new.organisation_id and kind = 'ai_api_key'
    ) then
      raise exception 'Add an API key before enabling Ask Qula';
    end if;
  end if;
  if new.config->>'baseUrl' is not null and new.config->>'baseUrl' <> '' and new.config->>'baseUrl' not like 'https://%' then
    raise exception 'The base URL must use https';
  end if;
  return new;
end;
$$;


--
-- Name: guard_code_unchanged(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_code_unchanged() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if upper(btrim(new.code)) is distinct from upper(btrim(old.code)) then
    raise exception 'A code cannot be changed.';
  end if;

  new.code := upper(btrim(old.code));
  return new;
end;
$$;


--
-- Name: guard_gl_code_product_use(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_gl_code_product_use() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.account_type is distinct from old.account_type then
    if new.account_type is distinct from 'Expense'
       and exists (
         select 1 from public.products where purchase_gl_code_id = new.id
       ) then
      raise exception 'That GL code is a purchase GL code on a product and must stay Expense';
    end if;

    if new.account_type is distinct from 'Income'
       and exists (
         select 1 from public.products where sales_gl_code_id = new.id
       ) then
      raise exception 'That GL code is a sales GL code on a product and must stay Income';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: guard_inbound_document_types(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_inbound_document_types() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_kind public.document_kind; v_type text;
begin
  if tg_op = 'UPDATE' and new.inbound_invoice_type_id is not distinct from old.inbound_invoice_type_id and new.inbound_credit_note_type_id is not distinct from old.inbound_credit_note_type_id then return new; end if;
  if private.org_role(new.organisation_id) not in ('owner', 'admin') then raise exception 'Only an owner or admin can choose the inbound document types'; end if;
  if new.inbound_invoice_type_id is not null then
    select document_kind, type into v_kind, v_type from public.transaction_types where id = new.inbound_invoice_type_id and organisation_id = new.organisation_id;
    if v_type is distinct from 'Purchases' or v_kind is distinct from 'invoice' then raise exception 'Choose a Purchases invoice type'; end if;
  end if;
  if new.inbound_credit_note_type_id is not null then
    select document_kind, type into v_kind, v_type from public.transaction_types where id = new.inbound_credit_note_type_id and organisation_id = new.organisation_id;
    if v_type is distinct from 'Purchases' or v_kind is distinct from 'credit_note' then raise exception 'Choose a Purchases credit note type'; end if;
  end if;
  return new;
end; $$;


--
-- Name: guard_last_owner(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_last_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_others integer;
begin
  if current_setting('fintran.deleting_organisation', true) = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if old.role = 'owner'
     and (
       tg_op = 'DELETE'
       or new.role is distinct from 'owner'
       or new.organisation_id is distinct from old.organisation_id
     )
  then
    select count(*) into v_others
    from public.organisation_access
    where organisation_id = old.organisation_id
      and role = 'owner'
      and user_id is distinct from old.user_id;

    if v_others = 0 then
      raise exception 'An organisation must keep at least one owner.';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: guard_organisation_peppol(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_organisation_peppol() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.peppol_id is not null and exists (
    select 1
    from public.organisation_defaults as other
    where other.organisation_id is distinct from new.organisation_id
      and other.peppol_scheme = new.peppol_scheme
      and lower(other.peppol_id) = lower(new.peppol_id)
  ) then
    raise exception 'This Peppol ID is already registered to another organisation.';
  end if;
  return new;
end;
$$;


--
-- Name: guard_posted_vat_rate(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_posted_vat_rate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.rate is distinct from old.rate
     or new.vat_type is distinct from old.vat_type
     or new.vat_category is distinct from old.vat_category then
    if exists (
      select 1
      from public.transaction_lines as line
      join public.transaction_headers as header on header.id = line.header_id
      where line.vat_rate_id = new.id
        and header.status in ('posted', 'void')
    ) then
      raise exception 'This VAT rate is used on posted documents. Create a new VAT code instead.';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_vat_rate_product_use(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_vat_rate_product_use() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.vat_type is distinct from old.vat_type then
    if new.vat_type is distinct from 'Expense'
       and exists (
         select 1 from public.products where purchase_vat_code_id = new.id
       ) then
      raise exception 'That VAT rate is a purchase VAT code on a product and must stay Expense';
    end if;

    if new.vat_type is distinct from 'Sales'
       and exists (
         select 1 from public.products where sales_vat_code_id = new.id
       ) then
      raise exception 'That VAT rate is a sales VAT code on a product and must stay Sales';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.profiles (id, email, display_name)
  values (
    new.id,
    coalesce(new.email, ''),
    left(
      coalesce(
        nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''),
        nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
        'User'
      ),
      80
    )
  );
  return new;
end;
$$;


--
-- Name: has_org_role(uuid, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_org_role(p_organisation_id uuid, p_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.org_role(p_organisation_id) = any (p_roles), false);
$$;


--
-- Name: iban_is_valid(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.iban_is_valid(p_iban text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_iban text;
  v_rearranged text;
  v_expanded text := '';
  v_index integer;
  v_character text;
begin
  v_iban := upper(regexp_replace(coalesce(p_iban, ''), '\s+', '', 'g'));
  if v_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$' then
    return false;
  end if;
  v_rearranged := substring(v_iban from 5) || substring(v_iban from 1 for 4);
  for v_index in 1..char_length(v_rearranged) loop
    v_character := substring(v_rearranged from v_index for 1);
    if v_character ~ '[A-Z]' then
      v_expanded := v_expanded || (ascii(v_character) - 55)::text;
    else
      v_expanded := v_expanded || v_character;
    end if;
  end loop;
  return (v_expanded::numeric % 97) = 1;
end;
$_$;


--
-- Name: is_org_member(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_org_member(org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.organisation_access
    where organisation_id = org
      and user_id = (select auth.uid())
  );
$$;


--
-- Name: is_tenant_manager(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_tenant_manager(tenant uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.organisation_access
    where tenant_id = tenant
      and user_id = (select auth.uid())
      and role in ('owner', 'admin')
  );
$$;


--
-- Name: issue_reference(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.issue_reference(p_transaction_type_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_reference integer;
begin
  perform 1
  from public.transaction_types
  where id = p_transaction_type_id
  for update;

  update public.transaction_types
  set last_reference = last_reference + 1
  where id = p_transaction_type_id
  returning last_reference into v_reference;

  if v_reference is null then
    raise exception 'Choose a Purchases transaction type';
  end if;

  return v_reference;
end;
$$;


--
-- Name: order_line_used(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.order_line_used(p_line_id uuid, p_except_line_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    coalesce((
      select sum(drawn.quantity)
      from public.transaction_lines as drawn
      join public.transaction_headers as header on header.id = drawn.header_id
      where drawn.source_line_id = p_line_id
        and drawn.id is distinct from p_except_line_id
        and header.status <> 'void'
    ), 0)
    - coalesce((
      select sum(credit.quantity)
      from public.transaction_lines as credit
      join public.transaction_headers as header on header.id = credit.header_id
      join public.transaction_lines as credited on credited.id = credit.credited_line_id
      where credited.source_line_id = p_line_id
        and credit.returns_to_order
        and header.status = 'posted'
    ), 0);
$$;


--
-- Name: org_role(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.org_role(org uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select role
  from public.organisation_access
  where organisation_id = org
    and user_id = (select auth.uid())
  limit 1;
$$;


--
-- Name: organisation_logo_allowed(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.organisation_logo_allowed(object_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  organisation uuid;
begin
  if object_name is null
     or object_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/(logo|snapshots/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$' then
    return false;
  end if;

  organisation := split_part(object_name, '/', 1)::uuid;
  return private.is_org_member(organisation);
end;
$_$;


--
-- Name: organisation_logo_manage(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.organisation_logo_manage(object_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  organisation uuid;
begin
  if object_name is null
     or object_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/logo$' then
    return false;
  end if;

  organisation := split_part(object_name, '/', 1)::uuid;
  return private.has_org_role(organisation, array['owner', 'admin']);
end;
$_$;


--
-- Name: organisation_snapshot_allowed(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.organisation_snapshot_allowed(object_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  organisation uuid;
begin
  if object_name is null
     or object_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/snapshots/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;

  organisation := split_part(object_name, '/', 1)::uuid;
  return private.is_org_member(organisation);
end;
$_$;


--
-- Name: plain_quantity(numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.plain_quantity(p_value numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select regexp_replace(regexp_replace(p_value::text, '(\.\d*?)0+$', '\1'), '\.$', '');
$_$;


--
-- Name: postal_address_text(text, text, text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.postal_address_text(p_line1 text, p_line2 text, p_line3 text, p_city text, p_post_code text, p_county text, p_country text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(concat_ws(
    E'\n',
    nullif(btrim(p_line1), ''),
    nullif(btrim(p_line2), ''),
    nullif(btrim(p_line3), ''),
    nullif(btrim(p_city), ''),
    nullif(btrim(p_county), ''),
    nullif(btrim(p_post_code), ''),
    nullif(btrim(p_country), '')
  ), '');
$$;


--
-- Name: prepare_bic(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_bic(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_bic text;
begin
  v_bic := nullif(upper(regexp_replace(coalesce(p_value, ''), '\s+', '', 'g')), '');
  if v_bic is null then
    return null;
  end if;
  if v_bic !~ '^[A-Z]{4}[A-Z]{2}[A-Z0-9]{2}([A-Z0-9]{3})?$' then
    raise exception 'Enter a BIC of 8 or 11 characters';
  end if;
  return v_bic;
end;
$_$;


--
-- Name: prepare_company_number(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_company_number(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_number text;
begin
  v_number := nullif(btrim(coalesce(p_value, '')), '');
  if v_number is null then
    return null;
  end if;
  if char_length(v_number) > 40 or v_number !~ '^[A-Za-z0-9][A-Za-z0-9 ./-]*$' then
    raise exception 'Company number can be up to 40 letters or numbers';
  end if;
  return v_number;
end;
$_$;


--
-- Name: prepare_iban(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_iban(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_iban text;
begin
  v_iban := nullif(upper(regexp_replace(coalesce(p_value, ''), '\s+', '', 'g')), '');
  if v_iban is null then
    return null;
  end if;
  if not private.iban_is_valid(v_iban) then
    raise exception 'Enter a valid IBAN';
  end if;
  return v_iban;
end;
$$;


--
-- Name: prepare_peppol(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_peppol(p_scheme text, p_id text) RETURNS TABLE(scheme text, identifier text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v_pattern text;
begin
  scheme := nullif(btrim(coalesce(p_scheme, '')), '');
  identifier := nullif(btrim(coalesce(p_id, '')), '');
  if (scheme is null) <> (identifier is null) then
    raise exception 'Enter both the Peppol scheme and the Peppol ID, or leave both blank';
  end if;
  if identifier is not null and identifier !~ '^[A-Za-z0-9._:-]{1,100}$' then
    raise exception 'Peppol ID can be up to 100 letters, digits, or . - _ : and cannot contain spaces';
  end if;
  if scheme is not null then
    select value_pattern into v_pattern
    from public.ref_eas
    where code = scheme;
    if not found then
      raise exception 'Choose a Peppol scheme';
    end if;
    if v_pattern is not null and identifier !~ v_pattern then
      raise exception 'This Peppol ID does not match the format for scheme %.', scheme;
    end if;
  end if;
  return next;
end;
$_$;


--
-- Name: prepare_postal(text, text, text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_postal(p_line1 text, p_line2 text, p_line3 text, p_city text, p_post_code text, p_county text, p_country text) RETURNS TABLE(line1 text, line2 text, line3 text, city text, post_code text, county text, country_code text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_country text;
begin
  line1 := nullif(btrim(p_line1), '');
  line2 := nullif(btrim(p_line2), '');
  line3 := nullif(btrim(p_line3), '');
  city := nullif(btrim(p_city), '');
  county := nullif(btrim(p_county), '');
  post_code := nullif(regexp_replace(upper(btrim(coalesce(p_post_code, ''))), '\s+', ' ', 'g'), '');
  if line1 is not null and char_length(line1) > 100 then
    raise exception 'Address line 1 can be up to 100 characters';
  end if;
  if line2 is not null and char_length(line2) > 100 then
    raise exception 'Address line 2 can be up to 100 characters';
  end if;
  if line3 is not null and char_length(line3) > 100 then
    raise exception 'Address line 3 can be up to 100 characters';
  end if;
  if city is not null and char_length(city) > 60 then
    raise exception 'City can be up to 60 characters';
  end if;
  if county is not null and char_length(county) > 60 then
    raise exception 'County can be up to 60 characters';
  end if;
  if post_code is not null and char_length(post_code) > 20 then
    raise exception 'Post code can be up to 20 characters';
  end if;

  v_country := upper(btrim(coalesce(p_country, '')));
  if v_country = '' then
    v_country := 'IE';
  end if;
  if exists (
    select 1 from public.ref_countries
    where code = v_country and vat_prefix_only
  ) or not exists (
    select 1 from public.ref_countries where code = v_country
  ) then
    raise exception 'Choose a postal country';
  end if;
  country_code := v_country;
  return next;
end;
$$;


--
-- Name: prepare_vat_number(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_vat_number(p_value text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v_number text;
begin
  v_number := nullif(upper(regexp_replace(coalesce(p_value, ''), '[[:space:]]', '', 'g')), '');
  if v_number is null then
    return null;
  end if;
  if v_number !~ '^[A-Z]{2}[A-Z0-9]{2,13}$'
     or not exists (select 1 from public.ref_countries where code = left(v_number, 2)) then
    raise exception 'Enter a VAT number with a country prefix, for example IE1234567T';
  end if;
  return v_number;
end;
$_$;


--
-- Name: purge_ai_feedback_text(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purge_ai_feedback_text() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_count integer;
begin
  update public.ai_feedback as feedback
  set question = null, answer = null, comment = null
  where (feedback.question is not null or feedback.answer is not null or feedback.comment is not null)
    and feedback.at < now() - make_interval(days => coalesce(
      (select settings.answer_retention_days from public.ai_settings as settings where settings.organisation_id = feedback.organisation_id),
      30
    ));
  get diagnostics v_count = row_count;

  -- Proposals nobody confirmed within their ten minutes are marked expired, so the action log is truthful.
  update public.ai_actions set status = 'expired', decided_at = now()
  where status = 'proposed' and expires_at <= now();
  return v_count;
end;
$$;


--
-- Name: purge_ai_feedback_text_nightly(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purge_ai_feedback_text_nightly() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if extract(hour from (now() at time zone 'Europe/Dublin')) <> 3 then
    return null;
  end if;
  return private.purge_ai_feedback_text();
end;
$$;


--
-- Name: record_e_document_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_e_document_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_detail jsonb := nullif(current_setting('fintran.e_document_detail', true), '')::jsonb;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return new;
  end if;
  if tg_op = 'UPDATE' and not private.e_document_transition_allowed(new.direction, old.status, new.status) then
    raise exception 'That e-document status change is not allowed';
  end if;
  if new.status = 'rejected' and nullif(btrim(new.rejection_reason), '') is null then
    raise exception 'A rejection needs a reason';
  end if;

  insert into public.e_document_events (
    e_document_id, organisation_id, from_status, to_status, actor, detail
  ) values (
    new.id,
    new.organisation_id,
    case when tg_op = 'UPDATE' then old.status else null end,
    new.status,
    (select auth.uid()),
    v_detail
  );
  return new;
end;
$$;


--
-- Name: refresh_transaction_header(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_transaction_header() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  header uuid := coalesce(new.header_id, old.header_id);
begin
  update public.transaction_headers
  set foreign_nett_amount = foreign_nett_amount
  where id = header;

  return null;
end;
$$;


--
-- Name: refresh_vat_breakdown(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_vat_breakdown() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and old.status in ('posted', 'void') then
    return null;
  end if;
  perform private.replace_vat_breakdown(new.id);
  return null;
end;
$$;


--
-- Name: replace_vat_breakdown(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replace_vat_breakdown(p_header_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_tenant uuid;
begin
  select organisation_id, tenant_id into v_org, v_tenant
  from public.transaction_headers
  where id = p_header_id;

  delete from public.transaction_vat_breakdown where header_id = p_header_id;

  insert into public.transaction_vat_breakdown (
    header_id, organisation_id, tenant_id, vat_category, vat_percentage,
    exemption_code, exemption_reason, taxable_amount, vat_amount
  )
  select
    p_header_id,
    v_org,
    v_tenant,
    line.vat_category,
    line.vat_percentage,
    min(line.exemption_code),
    min(line.exemption_reason),
    round(sum(line.nett_amount), 2),
    round(round(sum(line.nett_amount), 2) * line.vat_percentage / 100, 2)
  from public.transaction_lines as line
  where line.header_id = p_header_id
  group by line.vat_category, line.vat_percentage;
end;
$$;


--
-- Name: set_audit_columns(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.set_audit_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op is null then
    raise exception 'Audit columns are set by a trigger';
  end if;

  if tg_op = 'INSERT' then
    new.created_at := now();
    new.created_by := auth.uid();
    new.updated_at := now();
    new.updated_by := auth.uid();
  else
    new.created_at := old.created_at;
    new.created_by := old.created_by;
    new.updated_at := now();
    new.updated_by := auth.uid();
  end if;

  return new;
end;
$$;


--
-- Name: set_e_document_status(uuid, public.e_document_status, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.set_e_document_status(p_id uuid, p_to public.e_document_status, p_detail jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row public.e_documents%rowtype;
begin
  select * into v_row from public.e_documents where id = p_id for update;
  if v_row.id is null then
    raise exception 'That e-document was not found';
  end if;
  if not private.e_document_transition_allowed(v_row.direction, v_row.status, p_to) then
    raise exception 'That e-document status change is not allowed';
  end if;

  perform set_config('fintran.e_document_detail', coalesce(p_detail, '{}'::jsonb)::text, true);
  update public.e_documents
  set status = p_to,
      duplicate_of = coalesce(nullif(p_detail->>'duplicateOf', '')::uuid, duplicate_of),
      rejection_reason = case
        when p_to = 'rejected' then nullif(btrim(p_detail->>'reason'), '')
        else rejection_reason
      end,
      header_id = coalesce(nullif(p_detail->>'headerId', '')::uuid, header_id),
      validated_at = case
        when p_to in ('valid', 'invalid', 'duplicate') then coalesce(validated_at, now())
        else validated_at
      end,
      updated_at = now(),
      updated_by = (select auth.uid())
  where id = p_id;
end;
$$;


--
-- Name: shares_organisation(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.shares_organisation(other uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.organisation_access mine
    join public.organisation_access theirs
      on theirs.organisation_id = mine.organisation_id
    where mine.user_id = (select auth.uid())
      and theirs.user_id = other
  );
$$;


--
-- Name: signatures_match(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.signatures_match(p_left text, p_right text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare v_index integer; v_diff integer := 0;
begin
  if p_left is null or p_right is null or length(p_left) <> length(p_right) or length(p_left) = 0 then return false; end if;
  for v_index in 1..length(p_left) loop
    v_diff := v_diff + abs(ascii(substr(p_left, v_index, 1)) - ascii(substr(p_right, v_index, 1)));
  end loop;
  return v_diff = 0;
end; $$;


--
-- Name: slugify(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.slugify(input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select trim(both '-' from regexp_replace(lower(btrim(input)), '[^a-z0-9]+', '-', 'g'));
$$;


--
-- Name: split_legacy_address(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.split_legacy_address(p_address text) RETURNS TABLE(line1 text, line2 text, line3 text, needs_review boolean)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  parts text[];
  extra text;
begin
  if p_address is null or btrim(p_address) = '' then
    line1 := null;
    line2 := null;
    line3 := null;
    needs_review := false;
    return next;
    return;
  end if;

  parts := array(
    select btrim(line)
    from unnest(regexp_split_to_array(replace(p_address, E'\r\n', E'\n'), E'[\n\r]')) as line
    where btrim(line) <> ''
  );
  needs_review := true;
  line1 := left(parts[1], 100);
  if cardinality(parts) >= 2 then
    line2 := left(parts[2], 100);
  end if;
  if cardinality(parts) >= 3 then
    extra := array_to_string(parts[3:cardinality(parts)], ' ');
    line3 := left(extra, 100);
  end if;
  return next;
end;
$$;


--
-- Name: sync_order_closure(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_order_closure(p_order_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text;
  v_by_system boolean;
  v_covered boolean;
  v_flag text;
begin
  select header.status::text, header.closed_by_system into v_status, v_by_system
  from public.transaction_headers as header
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where header.id = p_order_id and kind.document_kind = 'order'
  for update of header;
  if v_status is null or v_status not in ('open', 'closed') then
    return;
  end if;

  -- Covered means posted invoices, less returning credit notes, cover every line that has a quantity.
  select not exists (
    select 1 from public.order_line_usage as usage
    where usage.header_id = p_order_id and usage.quantity > 0 and usage.invoiced < usage.quantity
  ) and exists (
    select 1 from public.transaction_lines as line where line.header_id = p_order_id and line.quantity > 0
  ) into v_covered;

  if v_status = 'open' and v_covered then
    null;
  elsif v_status = 'closed' and v_by_system and not v_covered then
    null;
  else
    return;
  end if;

  v_flag := current_setting('fintran.status_change', true);
  perform set_config('fintran.status_change', 'on', true);
  perform set_config('fintran.audit_reason', p_reason, true);
  if v_status = 'open' then
    update public.transaction_headers set status = 'closed', closed_by_system = true where id = p_order_id;
  else
    update public.transaction_headers set status = 'open', closed_by_system = false where id = p_order_id;
  end if;
  perform set_config('fintran.audit_reason', '', true);
  perform set_config('fintran.status_change', coalesce(nullif(v_flag, ''), 'off'), true);
end;
$$;


--
-- Name: sync_orders_after_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_orders_after_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind text;
  v_number text := coalesce(nullif(new.document_number, ''), 'a document');
  v_order record;
  v_over record;
  v_reason text;
begin
  select document_kind::text into v_kind from public.transaction_types where id = new.transaction_type_id;

  if v_kind = 'invoice' then
    v_reason := case when new.status = 'posted'
      then format('Posted invoices cover every line, after %s was posted.', v_number)
      else format('%s was voided, which left quantity to invoice.', v_number) end;
    for v_order in
      select distinct source.header_id
      from public.transaction_lines as line
      join public.transaction_lines as source on source.id = line.source_line_id
      where line.header_id = new.id
    loop
      perform private.sync_order_closure(v_order.header_id, v_reason);
    end loop;

  elsif v_kind = 'credit_note' then
    if new.status = 'void' then
      -- Voiding a credit note that returned quantity takes that quantity back. Refuse if it has since been invoiced.
      for v_over in
        select source.id, source.line_number, source.quantity, order_header.document_number
        from public.transaction_lines as credit
        join public.transaction_lines as credited on credited.id = credit.credited_line_id
        join public.transaction_lines as source on source.id = credited.source_line_id
        join public.transaction_headers as order_header on order_header.id = source.header_id
        where credit.header_id = new.id and credit.returns_to_order
        order by source.id
        for update of source
      loop
        if private.order_line_used(v_over.id, null) > v_over.quantity then
          raise exception 'This credit note gave quantity back to %, and that quantity has since been invoiced again. It cannot be voided.',
            coalesce(nullif(v_over.document_number, ''), 'an order');
        end if;
      end loop;
    end if;
    v_reason := case when new.status = 'posted'
      then format('Credit note %s returned quantity to the order.', v_number)
      else format('Credit note %s was voided, so posted invoices cover every line again.', v_number) end;
    for v_order in
      select distinct source.header_id
      from public.transaction_lines as credit
      join public.transaction_lines as credited on credited.id = credit.credited_line_id
      join public.transaction_lines as source on source.id = credited.source_line_id
      where credit.header_id = new.id and credit.returns_to_order
    loop
      perform private.sync_order_closure(v_order.header_id, v_reason);
    end loop;
  end if;
  return new;
end;
$$;


--
-- Name: validate_form_layout(jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_form_layout(p_layout jsonb, p_type text, p_kind text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_key text;
  v_item jsonb;
  v_seen text[] := array[]::text[];
  v_value text;
  v_allowed text[];
begin
  if jsonb_typeof(p_layout) is distinct from 'object' or char_length(p_layout::text) > 8000 then
    raise exception 'Form layout must be an object';
  end if;

  for v_key in select jsonb_object_keys(p_layout)
  loop
    if v_key not in (
      'version', 'title', 'pageSize', 'showLogo', 'showVatSummary', 'showBanking',
      'organisationFields', 'partyFields', 'headerFields', 'lineColumns'
    ) then
      raise exception 'Form layout has an unknown setting: %', v_key;
    end if;
  end loop;

  if (p_layout->>'version') is distinct from '1' then
    raise exception 'Form layout version must be 1';
  end if;
  if jsonb_typeof(p_layout->'title') is distinct from 'string'
     or char_length(btrim(p_layout->>'title')) < 1
     or char_length(btrim(p_layout->>'title')) > 80 then
    raise exception 'Form title must be 1 to 80 characters';
  end if;
  if p_layout ? 'pageSize'
     and (p_layout->>'pageSize') not in ('A4', 'A5', 'Letter', 'Legal') then
    raise exception 'Page size must be A4, A5, Letter, or Legal';
  end if;

  foreach v_key in array array['showLogo', 'showVatSummary', 'showBanking']
  loop
    if p_layout ? v_key and jsonb_typeof(p_layout->v_key) is distinct from 'boolean' then
      raise exception 'Form layout settings must be true or false';
    end if;
  end loop;

  foreach v_key in array array['organisationFields', 'partyFields', 'headerFields', 'lineColumns']
  loop
    if jsonb_typeof(p_layout->v_key) is distinct from 'array' then
      raise exception 'Form layout lists must be arrays';
    end if;
    v_seen := array[]::text[];
    v_allowed := case v_key
      when 'organisationFields' then array[
        'name','address','phone','contactEmail','website','contactName','vatNumber','companyNumber','peppolId','country'
      ]
      when 'partyFields' then array[
        'contactDetails','name','address','phone','email','website','code','peppolId','country','vatNumber'
      ]
      when 'headerFields' then array[
        'reference','documentNumber','transactionDate','terms','dueDate','orderNumber','currency','exchangeRate','paidAmount',
        'flex1','flex2','flex3','flex4','flex5','supplierReference','supplyDate',
        'buyerReference','contractReference','paymentTerms','invoicePeriod','precedingReference'
      ]
      else array[
        'date','item','description','tax','quantity','price','amount','discount','glCode','vatCode','department','costCentre',
        'unit','lineNote','order'
      ]
    end;
    for v_item in select value from jsonb_array_elements(p_layout->v_key)
    loop
      if jsonb_typeof(v_item) is distinct from 'string' then
        raise exception 'Form layout lists must contain field names';
      end if;
      v_value := v_item #>> '{}';
      if v_value = any (v_seen) then
        raise exception 'Form layout repeats the field %', v_value;
      end if;
      if not (v_value = any (v_allowed)) then
        raise exception 'Form layout has an unknown field: %', v_value;
      end if;
      v_seen := v_seen || v_value;
    end loop;
  end loop;

  if p_type = 'Sales' then
    if not (
      p_layout->'organisationFields' ? 'name'
      and p_layout->'organisationFields' ? 'address'
      and p_layout->'organisationFields' ? 'vatNumber'
    ) then
      raise exception 'A sales form must show the organisation name, address, and VAT number';
    end if;
    if not (
      p_layout->'partyFields' ? 'name'
      and p_layout->'partyFields' ? 'address'
    ) then
      raise exception 'A sales form must show the customer name and address';
    end if;
    if not (
      (p_layout->'headerFields' ? 'documentNumber' or p_layout->'headerFields' ? 'reference')
      and p_layout->'headerFields' ? 'transactionDate'
    ) then
      raise exception 'A sales form must show the document number and date';
    end if;
    if not (
      p_layout->'lineColumns' ? 'description'
      and p_layout->'lineColumns' ? 'quantity'
      and p_layout->'lineColumns' ? 'price'
      and p_layout->'lineColumns' ? 'tax'
      and p_layout->'lineColumns' ? 'amount'
    ) then
      raise exception 'A sales form must show the description, quantity, price, tax, and amount';
    end if;
    if (p_layout->>'showVatSummary') is distinct from 'true' then
      raise exception 'A sales form must show the VAT summary';
    end if;
    if p_kind = 'credit_note' and not (p_layout->'headerFields' ? 'precedingReference') then
      raise exception 'A sales credit note form must show the preceding invoice reference';
    end if;
  end if;
end;
$$;


--
-- Name: write_audit_log(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.write_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row jsonb;
  v_old jsonb;
  v_new jsonb;
  v_diff_old jsonb := '{}'::jsonb;
  v_diff_new jsonb := '{}'::jsonb;
  v_key text;
  v_ignore text[] := array['created_at', 'created_by', 'updated_at', 'updated_by'];
  v_row_id text;
  v_tenant uuid;
  v_organisation uuid;
  v_reason text := nullif(current_setting('fintran.audit_reason', true), '');
begin
  if tg_op is null then
    raise exception 'The audit log is written by a trigger';
  end if;

  if tg_table_name = 'transaction_headers' then
    v_ignore := v_ignore || array[
      'foreign_nett_amount',
      'foreign_vat_amount',
      'foreign_total_amount',
      'home_nett_amount',
      'home_vat_amount',
      'home_total_amount'
    ];
  end if;

  if tg_op = 'DELETE' then
    v_row := to_jsonb(old);
  else
    v_row := to_jsonb(new);
  end if;

  v_row_id := coalesce(v_row ->> 'id', v_row ->> 'organisation_id');
  v_tenant := (v_row ->> 'tenant_id')::uuid;
  v_organisation := nullif(v_row ->> 'organisation_id', '')::uuid;

  if tg_op = 'INSERT' then
    insert into public.audit_log (
      tenant_id, organisation_id, table_name, row_id, action, changed_by, new_values
    )
    values (
      v_tenant, v_organisation, tg_table_name, v_row_id, 'INSERT', auth.uid(), to_jsonb(new) - v_ignore
    );
  elsif tg_op = 'DELETE' then
    insert into public.audit_log (
      tenant_id, organisation_id, table_name, row_id, action, changed_by, old_values
    )
    values (
      v_tenant, v_organisation, tg_table_name, v_row_id, 'DELETE', auth.uid(), to_jsonb(old) - v_ignore
    );
  else
    v_old := to_jsonb(old) - v_ignore;
    v_new := to_jsonb(new) - v_ignore;
    for v_key in
      select key
      from (
        select jsonb_object_keys(v_old) as key
        union
        select jsonb_object_keys(v_new)
      ) keys
    loop
      if v_old -> v_key is distinct from v_new -> v_key then
        v_diff_old := v_diff_old || jsonb_build_object(v_key, v_old -> v_key);
        v_diff_new := v_diff_new || jsonb_build_object(v_key, v_new -> v_key);
      end if;
    end loop;

    if v_diff_old = '{}'::jsonb then
      return null;
    end if;

    -- A change the system made by itself says why, in the change details.
    if v_reason is not null and tg_table_name = 'transaction_headers' then
      v_diff_new := v_diff_new || jsonb_build_object('reason', v_reason);
    end if;

    insert into public.audit_log (
      tenant_id, organisation_id, table_name, row_id, action, changed_by, old_values, new_values
    )
    values (
      v_tenant, v_organisation, tg_table_name, v_row_id, 'UPDATE', auth.uid(), v_diff_old, v_diff_new
    );
  end if;

  return null;
end;
$$;


--
-- Name: ai_usage_allowance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_usage_allowance(p_organisation_id uuid) RETURNS TABLE(user_hour integer, organisation_month integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_org_member(p_organisation_id) then
    raise exception 'That organisation was not found';
  end if;
  return query
  select
    (select count(*)::integer from public.ai_usage
      where organisation_id = p_organisation_id
        and user_id = auth.uid()
        and at >= now() - interval '1 hour'),
    (select count(*)::integer from public.ai_usage
      where organisation_id = p_organisation_id
        and at >= date_trunc('month', now()));
end;
$$;


--
-- Name: clear_organisation_secret(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_organisation_secret(p_organisation_id uuid, p_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.has_org_role(p_organisation_id, array['owner', 'admin']) then
    raise exception 'Only an owner or admin can remove a secret';
  end if;
  delete from public.organisation_secrets
  where organisation_id = p_organisation_id and kind = p_kind;
  insert into public.audit_log (table_name, row_id, action, new_values, changed_by, tenant_id, organisation_id)
  select 'organisation_secrets', p_organisation_id::text, 'DELETE',
    jsonb_build_object('kind', p_kind),
    auth.uid(), tenant_id, id
  from public.organisations where id = p_organisation_id;
end;
$$;


--
-- Name: confirm_ai_action(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_ai_action(p_organisation_id uuid, p_token_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  v_row public.ai_actions;
  v_status text;
  v_version timestamptz;
begin
  if v_user is null or not private.is_org_member(p_organisation_id) then
    return 'unknown';
  end if;
  if not exists (
    select 1 from public.ai_settings
    where organisation_id = p_organisation_id and enabled and actions_enabled
  ) then
    return 'disabled';
  end if;

  update public.ai_actions
  set status = 'confirmed', decided_at = now()
  where token_hash = p_token_hash
    and status = 'proposed'
    and expires_at > now()
    and user_id = v_user
    and organisation_id = p_organisation_id
  returning * into v_row;

  if v_row.id is null then
    -- Nothing moved. Say why, without telling one person about another person's token.
    select status into v_status
    from public.ai_actions
    where token_hash = p_token_hash and user_id = v_user and organisation_id = p_organisation_id;
    if v_status is null then
      return 'unknown';
    end if;
    if v_status = 'proposed' then
      update public.ai_actions set status = 'expired', decided_at = now()
      where token_hash = p_token_hash and status = 'proposed';
      return 'expired';
    end if;
    if v_status in ('confirmed', 'failed') then
      return 'used';
    end if;
    return 'expired';
  end if;

  if v_row.action = 'post_draft' then
    select status::text, updated_at into v_status, v_version
    from public.transaction_headers
    where id = v_row.target_id and organisation_id = p_organisation_id;
    if v_status is distinct from 'draft' or v_version is distinct from v_row.target_version then
      update public.ai_actions
      set status = 'failed', detail = 'The document changed after it was proposed.'
      where id = v_row.id;
      return 'changed';
    end if;
  end if;
  return 'confirmed';
end;
$$;


--
-- Name: create_from_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_from_order(p_header_id uuid, p_type_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_source record;
  v_target_kind text;
  v_target_direction text;
  v_target_org uuid;
  v_lines jsonb;
begin
  if (select auth.uid()) is null then raise exception 'Sign in before creating a document'; end if;
  select header.*, kind.document_kind::text as kind, kind.type as direction
    into v_source
  from public.transaction_headers as header
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where header.id = p_header_id
  for update of header;
  if v_source.id is null then raise exception 'That order was not found'; end if;
  if not (select private.is_org_member(v_source.organisation_id)) then
    raise exception 'You are not a member of this organisation';
  end if;
  if v_source.kind not in ('order', 'requisition') then
    raise exception 'Only an order or a requisition can be turned into another document';
  end if;
  if v_source.status::text <> 'open' then
    raise exception 'Activate it first. Only an active order or requisition can be turned into another document.';
  end if;

  select document_kind::text, type, organisation_id into v_target_kind, v_target_direction, v_target_org
  from public.transaction_types where id = p_type_id;
  if v_target_org is distinct from v_source.organisation_id
     or v_target_direction is distinct from v_source.direction
     or not ((v_source.kind = 'order' and v_target_kind = 'invoice') or (v_source.kind = 'requisition' and v_target_kind = 'order')) then
    raise exception 'Choose an invoice type for an order, or an order type for a requisition';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'sourceLineId', line.id,
      'productId', line.product_id,
      'description', line.description,
      'glCodeId', line.gl_code_id,
      'departmentId', line.department_id,
      'costCentreId', line.cost_centre_id,
      'vatRateId', line.vat_rate_id,
      'quantity', remaining.quantity,
      'price', line.price,
      'discountAmount', case when line.quantity = 0 then 0 else round(line.discount_amount * remaining.quantity / line.quantity, 2) end,
      'unitCode', line.unit_code,
      'lineNote', line.line_note,
      'sellerItemId', line.seller_item_id,
      'orderLineReference', line.order_line_reference
    )
    order by line.line_number
  ) into v_lines
  from public.transaction_lines as line
  cross join lateral (
    select case
      when v_source.kind = 'order' then line.quantity - private.order_line_used(line.id, null)
      else line.quantity
    end as quantity
  ) as remaining
  where line.header_id = p_header_id and remaining.quantity > 0;

  if v_lines is null then
    raise exception 'Everything on this order has already been invoiced';
  end if;

  return public.save_document(jsonb_build_object(
    'transactionTypeId', p_type_id,
    'transactionDate', current_date,
    'supplierId', v_source.supplier_id,
    'customerId', v_source.customer_id,
    'partyName', v_source.party_name,
    'contactDetails', v_source.contact_details,
    'currencyId', v_source.currency_id,
    'exchangeRate', v_source.exchange_rate,
    'orderNumber', case when v_source.kind = 'order' and v_source.direction = 'Purchases' then v_source.document_number else v_source.order_number end,
    'salesOrderReference', case when v_source.kind = 'order' and v_source.direction = 'Sales' then v_source.document_number end,
    'buyerReference', v_source.buyer_reference,
    'contractReference', v_source.contract_reference,
    'paymentTerms', v_source.payment_terms,
    'lines', v_lines
  ));
end;
$$;


--
-- Name: create_organisation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_organisation(p_tenant_id uuid, organisation_name text, p_home_currency text DEFAULT 'EUR'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  uid uuid := (select auth.uid());
  organisation_id uuid;
  organisation_slug text;
  attempt integer := 0;
  v_code text := upper(btrim(coalesce(p_home_currency, '')));
begin
  if uid is null then
    raise exception 'Sign in before creating an organisation';
  end if;
  if not (select private.can_manage_tenant(p_tenant_id)) then
    raise exception 'You need an owner role in this tenant';
  end if;
  if char_length(btrim(organisation_name)) < 2 then
    raise exception 'Name needs at least 2 characters';
  end if;
  if not exists (
    select 1 from public.ref_currencies where code = v_code and active
  ) then
    raise exception 'Choose an active ISO currency';
  end if;

  organisation_slug := private.slugify(organisation_name);
  if organisation_slug = '' then
    raise exception 'Name needs at least one letter or number';
  end if;

  while exists (
    select 1 from public.organisations
    where tenant_id = p_tenant_id and slug = organisation_slug
  ) loop
    attempt := attempt + 1;
    if attempt > 5 then
      raise exception 'Could not reserve a unique organisation name';
    end if;
    organisation_slug := private.slugify(organisation_name) || '-' || substr(extensions.gen_random_uuid()::text, 1, 4);
  end loop;

  perform set_config('fintran.home_currency', v_code, true);

  insert into public.organisations (tenant_id, name, slug)
  values (p_tenant_id, btrim(organisation_name), organisation_slug)
  returning id into organisation_id;

  insert into public.organisation_access (tenant_id, organisation_id, user_id, role)
  values (p_tenant_id, organisation_id, uid, 'owner');

  return organisation_id;
end;
$$;


--
-- Name: create_tenant(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tenant(tenant_name text, organisation_name text, p_home_currency text DEFAULT 'EUR'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  uid uuid := (select auth.uid());
  tenant_id uuid;
  organisation_id uuid;
  tenant_slug text;
  organisation_slug text;
  attempt integer := 0;
  v_code text := upper(btrim(coalesce(p_home_currency, '')));
begin
  if uid is null then
    raise exception 'Sign in before creating a tenant';
  end if;
  if char_length(btrim(tenant_name)) < 2 or char_length(btrim(organisation_name)) < 2 then
    raise exception 'Names need at least 2 characters';
  end if;
  if not exists (
    select 1 from public.ref_currencies where code = v_code and active
  ) then
    raise exception 'Choose an active ISO currency';
  end if;

  tenant_slug := private.slugify(tenant_name);
  organisation_slug := private.slugify(organisation_name);
  if tenant_slug = '' or organisation_slug = '' then
    raise exception 'Names need at least one letter or number';
  end if;

  while exists (select 1 from public.tenants where slug = tenant_slug) loop
    attempt := attempt + 1;
    if attempt > 5 then
      raise exception 'Could not reserve a unique tenant name';
    end if;
    tenant_slug := private.slugify(tenant_name) || '-' || substr(extensions.gen_random_uuid()::text, 1, 4);
  end loop;

  perform set_config('fintran.home_currency', v_code, true);

  insert into public.tenants (name, slug)
  values (btrim(tenant_name), tenant_slug)
  returning id into tenant_id;

  insert into public.organisations (tenant_id, name, slug)
  values (tenant_id, btrim(organisation_name), organisation_slug)
  returning id into organisation_id;

  insert into public.organisation_access (tenant_id, organisation_id, user_id, role)
  values (tenant_id, organisation_id, uid, 'owner');

  return jsonb_build_object('tenant_id', tenant_id, 'organisation_id', organisation_id);
end;
$$;


--
-- Name: delete_organisation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_organisation(p_organisation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant uuid;
  v_organisations integer;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in before deleting an organisation';
  end if;
  if not (select private.has_org_role(p_organisation_id, array['owner'])) then
    raise exception 'You need an owner role to delete an organisation';
  end if;

  select tenant_id into v_tenant
  from public.organisations
  where id = p_organisation_id;

  if v_tenant is null then
    raise exception 'That organisation could not be deleted';
  end if;
  if exists (
    select 1 from public.transaction_headers where organisation_id = p_organisation_id
  ) then
    raise exception 'This organisation has documents and cannot be deleted.';
  end if;
  if exists (
    select 1 from public.e_documents where organisation_id = p_organisation_id
  ) then
    raise exception 'This organisation has e-documents and cannot be deleted.';
  end if;

  select count(*) into v_organisations
  from public.organisations
  where tenant_id = v_tenant;

  if v_organisations <= 1 then
    raise exception 'A tenant must keep at least one organisation';
  end if;

  perform set_config('fintran.deleting_organisation', 'on', true);
  delete from public.organisations where id = p_organisation_id;
  perform set_config('fintran.deleting_organisation', 'off', true);
end;
$$;


--
-- Name: e_document_xml(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e_document_xml(p_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v_xml text;
begin
  select content.xml into v_xml from public.e_document_contents as content join public.e_documents as document on document.id = content.e_document_id where content.e_document_id = p_id and private.is_org_member(document.organisation_id);
  return v_xml;
end; $$;


--
-- Name: en16931_amount(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.en16931_amount(p_value numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select case when p_value is null then null else to_char(round(p_value, 2), 'FM999999999999990.00') end; $$;


--
-- Name: en16931_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.en16931_document(p_header_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v_source jsonb; v_seller jsonb; v_buyer jsonb; v_line jsonb; v_row jsonb;
  v_lines jsonb := '[]'::jsonb; v_breakdown jsonb := '[]'::jsonb; v_number text;
  v_seller_address jsonb; v_buyer_address jsonb; v_seller_contact jsonb; v_buyer_contact jsonb;
  v_payment jsonb; v_seller_party jsonb; v_buyer_party jsonb; v_allowance jsonb; v_item text;
begin
  v_source := public.en16931_source(p_header_id);
  if v_source is null then return null; end if;
  if v_source->>'kind' in ('order', 'requisition') then raise exception 'An order is not exported'; end if;
  v_seller := v_source->'seller';
  v_buyer := v_source->'buyer';
  v_number := nullif(v_source->>'invoiceNumber', '');
  v_seller_address := jsonb_strip_nulls(jsonb_build_object('BT-35', nullif(v_seller->>'line1', ''), 'BT-36', nullif(v_seller->>'line2', ''), 'BT-162', nullif(v_seller->>'line3', ''), 'BT-37', nullif(v_seller->>'city', ''), 'BT-38', nullif(v_seller->>'postCode', ''), 'BT-39', nullif(v_seller->>'county', ''), 'BT-40', nullif(v_seller->>'country', '')));
  v_buyer_address := jsonb_strip_nulls(jsonb_build_object('BT-35', nullif(v_buyer->>'line1', ''), 'BT-36', nullif(v_buyer->>'line2', ''), 'BT-162', nullif(v_buyer->>'line3', ''), 'BT-37', nullif(v_buyer->>'city', ''), 'BT-38', nullif(v_buyer->>'postCode', ''), 'BT-39', nullif(v_buyer->>'county', ''), 'BT-40', nullif(v_buyer->>'country', '')));
  if v_seller_address = '{}'::jsonb then v_seller_address := null; end if;
  if v_buyer_address = '{}'::jsonb then v_buyer_address := null; end if;
  v_seller_contact := jsonb_strip_nulls(jsonb_build_object('BT-41', nullif(v_seller->>'contact', ''), 'BT-42', nullif(v_seller->>'phone', ''), 'BT-43', nullif(v_seller->>'email', '')));
  v_buyer_contact := jsonb_strip_nulls(jsonb_build_object('BT-56', nullif(v_buyer->>'contact', ''), 'BT-57', nullif(v_buyer->>'phone', ''), 'BT-58', nullif(v_buyer->>'email', '')));
  if v_seller_contact = '{}'::jsonb then v_seller_contact := null; end if;
  if v_buyer_contact = '{}'::jsonb then v_buyer_contact := null; end if;
  v_seller_party := jsonb_strip_nulls(jsonb_build_object('BT-27', nullif(v_seller->>'name', ''), 'BT-29', case when v_source->>'direction' = 'Purchases' then nullif(v_seller->>'code', '') end, 'BT-30', nullif(v_seller->>'company', ''), 'BT-31', nullif(v_seller->>'vat', ''), 'BT-34', case when nullif(v_seller->>'peppolScheme', '') is not null and nullif(v_seller->>'peppolId', '') is not null then jsonb_build_object('scheme', v_seller->>'peppolScheme', 'value', v_seller->>'peppolId') end, 'BG-5', v_seller_address, 'BG-6', v_seller_contact));
  v_buyer_party := jsonb_strip_nulls(jsonb_build_object('BT-44', nullif(v_buyer->>'name', ''), 'BT-46', case when v_source->>'direction' = 'Sales' then nullif(v_buyer->>'code', '') end, 'BT-47', nullif(v_buyer->>'company', ''), 'BT-48', nullif(v_buyer->>'vat', ''), 'BT-49', case when nullif(v_buyer->>'peppolScheme', '') is not null and nullif(v_buyer->>'peppolId', '') is not null then jsonb_build_object('scheme', v_buyer->>'peppolScheme', 'value', v_buyer->>'peppolId') end, 'BG-8', v_buyer_address, 'BG-9', v_buyer_contact));
  if v_seller_party = '{}'::jsonb then v_seller_party := null; end if;
  if v_buyer_party = '{}'::jsonb then v_buyer_party := null; end if;
  v_payment := jsonb_strip_nulls(jsonb_build_object('BT-81', nullif(v_source->>'paymentMeans', ''), 'BT-83', v_number, 'BG-17', case when nullif(v_seller->>'iban', '') is not null then jsonb_strip_nulls(jsonb_build_object('BT-84', v_seller->>'iban', 'BT-85', nullif(v_seller->>'accountName', ''), 'BT-86', nullif(v_seller->>'bic', ''))) end));
  if v_payment = '{}'::jsonb then v_payment := null; end if;
  for v_line in select value from jsonb_array_elements(v_source->'lines') loop
    v_allowance := null;
    if coalesce((v_line->>'discount')::numeric, 0) <> 0 then
      v_allowance := jsonb_build_array(jsonb_build_object('BT-136', public.en16931_amount((v_line->>'discount')::numeric), 'BT-140', '95'));
    end if;
    v_item := nullif(v_line->>'sellerItem', '');
    if v_source->>'direction' = 'Sales' then v_item := nullif(v_line->>'productCode', ''); end if;
    v_lines := v_lines || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'BT-126', v_line->>'line', 'BT-127', nullif(v_line->>'note', ''),
      'BT-132', nullif(v_line->>'orderLine', ''),
      'BT-129', regexp_replace(regexp_replace(to_char((v_line->>'quantity')::numeric, 'FM999999999990.9999'), '0+$', ''), '\.$', ''),
      'BT-130', nullif(v_line->>'unit', ''), 'BT-131', public.en16931_amount((v_line->>'nett')::numeric),
      'BG-27', v_allowance, 'BG-29', jsonb_build_object('BT-146', public.en16931_price((v_line->>'price')::numeric)),
      'BG-30', jsonb_strip_nulls(jsonb_build_object('BT-151', nullif(v_line->>'category', ''), 'BT-152', public.en16931_amount((v_line->>'rate')::numeric))),
      'BG-31', jsonb_strip_nulls(jsonb_build_object('BT-153', nullif(v_line->>'description', ''), 'BT-155', v_item))
    )));
  end loop;
  for v_row in select value from jsonb_array_elements(v_source->'breakdown') loop
    v_breakdown := v_breakdown || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'BT-116', public.en16931_amount((v_row->>'taxable')::numeric),
      'BT-117', public.en16931_amount((v_row->>'vat')::numeric),
      'BT-118', v_row->>'category',
      'BT-119', public.en16931_amount((v_row->>'rate')::numeric),
      'BT-120', nullif(v_row->>'exemptionReason', ''),
      'BT-121', nullif(v_row->>'exemptionCode', '')
    )));
  end loop;
  return jsonb_strip_nulls(jsonb_build_object(
    'BT-1', v_number,
    'BT-2', to_char((v_source->>'issueDate')::date, 'YYYY-MM-DD'),
    'BT-3', case v_source->>'kind' when 'credit_note' then '381' else '380' end,
    'BT-5', v_source->>'currency',
    'BT-6', case when v_source->>'homeCurrency' is not null and v_source->>'homeCurrency' is distinct from v_source->>'currency' then v_source->>'homeCurrency' end,
    'BT-9', case when v_source->>'dueDate' is not null then to_char((v_source->>'dueDate')::date, 'YYYY-MM-DD') end,
    'BT-10', nullif(v_source->>'buyerReference', ''),
    'BT-12', nullif(v_source->>'contractReference', ''),
    'BT-13', nullif(v_source->>'orderNumber', ''),
    'BT-14', nullif(v_source->>'salesOrderReference', ''),
    'BT-20', nullif(v_source->>'paymentTerms', ''),
    'BT-22', nullif(v_source->>'notes', ''),
    'BT-23', 'urn:fdc:peppol.eu:2017:poacc:billing:01:1.0',
    'BT-24', 'urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0',
    'BT-72', case when v_source->>'supplyDate' is not null then to_char((v_source->>'supplyDate')::date, 'YYYY-MM-DD') end,
    'BG-3', case when nullif(v_source->>'precedingReference', '') is not null then jsonb_strip_nulls(jsonb_build_object('BT-25', v_source->>'precedingReference', 'BT-26', case when v_source->>'precedingDate' is not null then to_char((v_source->>'precedingDate')::date, 'YYYY-MM-DD') end)) end,
    'BG-4', v_seller_party, 'BG-7', v_buyer_party,
    'BG-14', case when v_source->>'periodStart' is not null and v_source->>'periodEnd' is not null then jsonb_build_object('BT-73', to_char((v_source->>'periodStart')::date, 'YYYY-MM-DD'), 'BT-74', to_char((v_source->>'periodEnd')::date, 'YYYY-MM-DD')) end,
    'BG-16', v_payment,
    'BG-22', jsonb_strip_nulls(jsonb_build_object(
      'BT-106', public.en16931_amount((v_source->>'lineNettSum')::numeric),
      'BT-109', public.en16931_amount((v_source->>'nett')::numeric),
      'BT-110', public.en16931_amount((v_source->>'vat')::numeric),
      'BT-111', case when v_source->>'homeCurrency' is not null and v_source->>'homeCurrency' is distinct from v_source->>'currency' then public.en16931_amount((v_source->>'homeVat')::numeric) end,
      'BT-112', public.en16931_amount((v_source->>'total')::numeric),
      'BT-113', case when coalesce((v_source->>'paid')::numeric, 0) <> 0 then public.en16931_amount((v_source->>'paid')::numeric) end,
      'BT-114', case when coalesce((v_source->>'rounding')::numeric, 0) <> 0 then public.en16931_amount((v_source->>'rounding')::numeric) end,
      'BT-115', public.en16931_amount((v_source->>'due')::numeric)
    )),
    'BG-23', case when v_breakdown = '[]'::jsonb then null else v_breakdown end,
    'BG-25', case when v_lines = '[]'::jsonb then null else v_lines end
  ));
end;
$_$;


--
-- Name: en16931_price(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.en16931_price(p_value numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ select case when p_value is null then null else to_char(round(p_value, 4), 'FM999999999999990.0000') end; $$;


--
-- Name: en16931_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.en16931_readiness(p_header_id uuid) RETURNS TABLE(rule_id text, severity text, business_term text, message text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v_source jsonb;
  v_severity text;
  v_seller jsonb;
  v_buyer jsonb;
  v_line jsonb;
  v_row jsonb;
  v_vat text;
  v_prefix text;
begin
  v_source := public.en16931_source(p_header_id);
  if v_source is null then
    return;
  end if;
  v_severity := case when v_source->>'direction' = 'Sales' then 'error' else 'warning' end;
  v_seller := v_source->'seller';
  v_buyer := v_source->'buyer';
  if nullif(v_seller->>'name', '') is null then
    rule_id := 'BR-06'; severity := v_severity; business_term := 'BT-27'; message := 'The seller name is missing.'; return next;
  end if;
  if nullif(v_buyer->>'name', '') is null then
    rule_id := 'BR-07'; severity := v_severity; business_term := 'BT-44'; message := 'The buyer name is missing.'; return next;
  end if;
  if nullif(v_seller->>'line1', '') is null or nullif(v_seller->>'city', '') is null or nullif(v_seller->>'country', '') is null then
    rule_id := 'BR-08'; severity := v_severity; business_term := 'BG-5'; message := 'The seller postal address needs a street, a city, and a country.'; return next;
  end if;
  if nullif(v_buyer->>'line1', '') is null or nullif(v_buyer->>'city', '') is null or nullif(v_buyer->>'country', '') is null then
    rule_id := 'BR-10'; severity := v_severity; business_term := 'BG-8'; message := 'The buyer postal address needs a street, a city, and a country.'; return next;
  end if;
  v_vat := nullif(v_seller->>'vat', '');
  if v_vat is null and exists (select 1 from jsonb_array_elements(v_source->'lines') as line where line->>'category' = 'S') then
    rule_id := 'BR-S-02'; severity := v_severity; business_term := 'BT-31'; message := 'A standard-rated line needs the seller VAT identifier.'; return next;
  end if;
  if v_vat is not null then
    v_prefix := upper(substring(v_vat from 1 for 2));
    if char_length(v_vat) < 4 or substring(v_vat from 3) !~ '^[A-Z0-9]{2,13}$' or not (exists (select 1 from public.ref_countries where code = v_prefix and vat_prefix_only is false) or v_prefix = 'EL') then
      rule_id := 'BR-CO-09'; severity := v_severity; business_term := 'BT-31'; message := 'The seller VAT identifier needs a country prefix, such as IE or EL.'; return next;
    end if;
  end if;
  if exists (select 1 from jsonb_array_elements(v_source->'lines') as line where line->>'category' = 'K') and nullif(v_buyer->>'vat', '') is null then
    rule_id := 'BR-IC-02'; severity := v_severity; business_term := 'BT-48'; message := 'An intra-Community line needs the buyer VAT identifier.'; return next;
  end if;
  if exists (select 1 from jsonb_array_elements(v_source->'lines') as line where line->>'category' = 'AE') and nullif(v_buyer->>'vat', '') is null and nullif(v_buyer->>'company', '') is null then
    rule_id := 'BR-AE-02'; severity := v_severity; business_term := 'BT-48'; message := 'A reverse-charge line needs the buyer VAT identifier or company number.'; return next;
  end if;
  if nullif(v_seller->>'peppolScheme', '') is null or nullif(v_seller->>'peppolId', '') is null then
    rule_id := 'PEPPOL-EN16931-R020'; severity := v_severity; business_term := 'BT-34'; message := 'The seller electronic address is missing.'; return next;
  end if;
  if nullif(v_buyer->>'peppolScheme', '') is null or nullif(v_buyer->>'peppolId', '') is null then
    rule_id := 'PEPPOL-EN16931-R010'; severity := v_severity; business_term := 'BT-49'; message := 'The buyer electronic address is missing.'; return next;
  end if;
  if nullif(v_source->>'buyerReference', '') is null and nullif(v_source->>'orderNumber', '') is null then
    rule_id := 'PEPPOL-EN16931-R003'; severity := v_severity; business_term := 'BT-10'; message := 'A buyer reference or purchase order reference is required.'; return next;
  end if;
  if coalesce((v_source->>'due')::numeric, 0) > 0 and v_source->>'dueDate' is null and nullif(v_source->>'paymentTerms', '') is null then
    rule_id := 'BR-CO-25'; severity := v_severity; business_term := 'BT-9'; message := 'When an amount is due, enter a due date or payment terms.'; return next;
  end if;
  if v_source->>'direction' = 'Purchases' and nullif(v_source->>'invoiceNumber', '') is null then
    rule_id := 'FINTRAN-BT-1'; severity := 'warning'; business_term := 'BT-1'; message := 'This purchase has no supplier invoice number, so the invoice number is left out of the export.'; return next;
  end if;
  if round(coalesce((v_source->>'lineNettSum')::numeric, 0), 2) is distinct from round(coalesce((v_source->>'nett')::numeric, 0), 2) then
    rule_id := 'BR-CO-10'; severity := v_severity; business_term := 'BT-106'; message := 'The sum of the line nett amounts does not match the document nett.'; return next;
  end if;
  if round(coalesce((v_source->>'breakdownVatSum')::numeric, 0), 2) is distinct from round(coalesce((v_source->>'vat')::numeric, 0), 2) then
    rule_id := 'BR-CO-14'; severity := v_severity; business_term := 'BT-110'; message := 'The document VAT does not match the VAT breakdown.'; return next;
  end if;
  if round(coalesce((v_source->>'nett')::numeric, 0) + coalesce((v_source->>'vat')::numeric, 0), 2) is distinct from round(coalesce((v_source->>'total')::numeric, 0), 2) then
    rule_id := 'BR-CO-15'; severity := v_severity; business_term := 'BT-112'; message := 'The total with VAT does not equal the nett plus the VAT.'; return next;
  end if;
  if round(coalesce((v_source->>'total')::numeric, 0) - coalesce((v_source->>'paid')::numeric, 0) + coalesce((v_source->>'rounding')::numeric, 0), 2) is distinct from round(coalesce((v_source->>'due')::numeric, 0), 2) then
    rule_id := 'BR-CO-16'; severity := v_severity; business_term := 'BT-115'; message := 'The amount due does not equal the total, minus paid, plus rounding.'; return next;
  end if;
  for v_row in select value from jsonb_array_elements(v_source->'breakdown') loop
    if round(coalesce((v_row->>'vat')::numeric, 0), 2) is distinct from round(coalesce((v_row->>'taxable')::numeric, 0) * coalesce((v_row->>'rate')::numeric, 0) / 100, 2) then
      rule_id := 'BR-CO-17'; severity := v_severity; business_term := 'BT-117'; message := 'A VAT breakdown amount does not match its taxable amount times the rate.'; return next;
    end if;
    if v_row->>'category' in ('E', 'AE', 'G', 'K', 'O') and nullif(v_row->>'exemptionCode', '') is null and nullif(v_row->>'exemptionReason', '') is null then
      rule_id := case v_row->>'category' when 'E' then 'BR-E-10' when 'AE' then 'BR-AE-10' when 'G' then 'BR-G-10' when 'K' then 'BR-IC-10' else 'BR-O-10' end;
      severity := v_severity; business_term := 'BT-120'; message := 'This VAT category needs an exemption reason.'; return next;
    end if;
  end loop;
  if jsonb_array_length(v_source->'lines') < 1 then
    rule_id := 'BR-16'; severity := v_severity; business_term := 'BG-25'; message := 'The document needs at least one line.'; return next;
  end if;
  if v_source->>'kind' = 'credit_note' and nullif(v_source->>'precedingReference', '') is null then
    rule_id := 'FINTRAN-CREDIT'; severity := v_severity; business_term := 'BT-25'; message := 'A credit note needs the invoice it applies to.'; return next;
  end if;
  if v_source->>'paymentMeans' in ('30', '58') and nullif(v_seller->>'iban', '') is null then
    rule_id := 'BR-61'; severity := v_severity; business_term := 'BT-84'; message := 'A credit transfer needs the seller IBAN.'; return next;
  end if;
  if coalesce((v_seller->>'needsReview')::boolean, false) or coalesce((v_buyer->>'needsReview')::boolean, false) then
    rule_id := 'FINTRAN-ADDRESS-REVIEW'; severity := 'warning'; business_term := 'BG-5'; message := 'An address was split from older text and still needs review.'; return next;
  end if;
end;
$_$;


--
-- Name: en16931_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.en16931_source(p_header_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_header public.transaction_headers%rowtype;
  v_direction text;
  v_kind text;
  v_currency text;
  v_home text;
  v_seller jsonb;
  v_buyer jsonb;
  v_org jsonb;
  v_counterparty jsonb;
  v_lines jsonb;
  v_breakdown jsonb;
  v_line_nett numeric;
  v_breakdown_vat numeric;
begin
  select * into v_header
  from public.transaction_headers
  where id = p_header_id;

  if v_header.id is null then
    return null;
  end if;

  select type, document_kind::text into v_direction, v_kind
  from public.transaction_types
  where id = v_header.transaction_type_id;

  select iso_code into v_currency
  from public.currencies
  where id = v_header.currency_id
    and organisation_id = v_header.organisation_id;

  select currencies.iso_code into v_home
  from public.organisation_defaults as defaults
  join public.currencies as currencies
    on currencies.id = defaults.home_currency_id
   and currencies.organisation_id = defaults.organisation_id
  where defaults.organisation_id = v_header.organisation_id;

  select coalesce(sum(nett_amount), 0), coalesce(jsonb_agg(jsonb_build_object(
    'line', line_number,
    'note', line_note,
    'quantity', quantity,
    'unit', unit_code,
    'nett', nett_amount,
    'price', price,
    'discount', discount_amount,
    'category', vat_category,
    'rate', vat_percentage,
    'description', description,
    'sellerItem', seller_item_id,
    'orderLine', order_line_reference,
    'productCode', (select code from public.products where id = transaction_lines.product_id)
  ) order by line_number), '[]'::jsonb)
    into v_line_nett, v_lines
  from public.transaction_lines
  where header_id = v_header.id;

  select coalesce(sum(vat_amount), 0), coalesce(jsonb_agg(jsonb_build_object(
    'category', vat_category,
    'rate', vat_percentage,
    'taxable', taxable_amount,
    'vat', vat_amount,
    'exemptionCode', exemption_code,
    'exemptionReason', exemption_reason
  ) order by vat_category, vat_percentage), '[]'::jsonb)
    into v_breakdown_vat, v_breakdown
  from public.transaction_vat_breakdown
  where header_id = v_header.id;

  if v_header.status in ('posted', 'void') then
    v_org := jsonb_strip_nulls(jsonb_build_object(
      'name', v_header.issuer_snapshot->>'name',
      'line1', v_header.issuer_snapshot->>'addressLine1',
      'line2', v_header.issuer_snapshot->>'addressLine2',
      'line3', v_header.issuer_snapshot->>'addressLine3',
      'city', v_header.issuer_snapshot->>'city',
      'postCode', v_header.issuer_snapshot->>'postCode',
      'county', v_header.issuer_snapshot->>'county',
      'country', v_header.issuer_snapshot->>'countryCode',
      'vat', v_header.issuer_snapshot->>'vatNumber',
      'company', v_header.issuer_snapshot->>'companyNumber',
      'peppolScheme', v_header.issuer_snapshot->>'peppolScheme',
      'peppolId', v_header.issuer_snapshot->>'peppolId',
      'phone', v_header.issuer_snapshot->>'phone',
      'email', v_header.issuer_snapshot->>'contactEmail',
      'contact', v_header.issuer_snapshot->>'contactName',
      'iban', v_header.issuer_snapshot->>'iban',
      'bic', v_header.issuer_snapshot->>'bic',
      'accountName', v_header.issuer_snapshot->>'bankAccountName'
    ));
    v_counterparty := jsonb_strip_nulls(jsonb_build_object(
      'name', v_header.party_snapshot->>'name',
      'code', v_header.party_snapshot->>'code',
      'line1', v_header.party_snapshot->>'addressLine1',
      'line2', v_header.party_snapshot->>'addressLine2',
      'line3', v_header.party_snapshot->>'addressLine3',
      'city', v_header.party_snapshot->>'city',
      'postCode', v_header.party_snapshot->>'postCode',
      'county', v_header.party_snapshot->>'county',
      'country', v_header.party_snapshot->>'countryCode',
      'vat', v_header.party_snapshot->>'vatNumber',
      'company', v_header.party_snapshot->>'companyNumber',
      'peppolScheme', v_header.party_snapshot->>'peppolScheme',
      'peppolId', v_header.party_snapshot->>'peppolId',
      'phone', v_header.party_snapshot->>'phone',
      'email', v_header.party_snapshot->>'email',
      'contact', v_header.party_snapshot->>'contactDetails'
    ));
  else
    select jsonb_strip_nulls(jsonb_build_object(
      'name', organisation.name,
      'line1', defaults.address_line1,
      'line2', defaults.address_line2,
      'line3', defaults.address_line3,
      'city', defaults.city,
      'postCode', defaults.post_code,
      'county', defaults.county,
      'country', defaults.country_code,
      'vat', defaults.vat_number,
      'company', defaults.company_number,
      'peppolScheme', defaults.peppol_scheme,
      'peppolId', defaults.peppol_id,
      'phone', defaults.phone,
      'email', defaults.contact_email,
      'contact', defaults.contact_name,
      'iban', defaults.iban,
      'bic', defaults.bic,
      'accountName', defaults.bank_account_name,
      'needsReview', defaults.address_needs_review
    )) into v_org
    from public.organisations as organisation
    join public.organisation_defaults as defaults
      on defaults.organisation_id = organisation.id
    where organisation.id = v_header.organisation_id;

    if v_direction = 'Sales' then
      select jsonb_strip_nulls(jsonb_build_object(
        'name', customers.name,
        'code', customers.code,
        'line1', customers.address_line1,
        'line2', customers.address_line2,
        'line3', customers.address_line3,
        'city', customers.city,
        'postCode', customers.post_code,
        'county', customers.county,
        'country', customers.country_code,
        'vat', customers.vat_number,
        'company', customers.company_number,
        'peppolScheme', customers.peppol_scheme,
        'peppolId', customers.peppol_id,
        'phone', customers.phone,
        'email', customers.email,
        'contact', customers.contact_details,
        'needsReview', customers.address_needs_review
      )) into v_counterparty
      from public.customers
      where id = v_header.customer_id
        and organisation_id = v_header.organisation_id;
    else
      select jsonb_strip_nulls(jsonb_build_object(
        'name', suppliers.name,
        'code', suppliers.code,
        'line1', suppliers.address_line1,
        'line2', suppliers.address_line2,
        'line3', suppliers.address_line3,
        'city', suppliers.city,
        'postCode', suppliers.post_code,
        'county', suppliers.county,
        'country', suppliers.country_code,
        'vat', suppliers.vat_number,
        'company', suppliers.company_number,
        'peppolScheme', suppliers.peppol_scheme,
        'peppolId', suppliers.peppol_id,
        'phone', suppliers.phone,
        'email', suppliers.email,
        'contact', suppliers.contact_details,
        'needsReview', suppliers.address_needs_review
      )) into v_counterparty
      from public.suppliers
      where id = v_header.supplier_id
        and organisation_id = v_header.organisation_id;
    end if;
  end if;

  if v_direction = 'Sales' then
    v_seller := v_org;
    v_buyer := v_counterparty;
  else
    v_seller := v_counterparty;
    v_buyer := v_org;
  end if;

  return jsonb_build_object(
    'direction', v_direction,
    'kind', v_kind,
    'status', v_header.status,
    'invoiceNumber', case
      when v_direction = 'Sales' then nullif(btrim(v_header.document_number), '')
      else nullif(btrim(v_header.supplier_reference), '')
    end,
    'issueDate', v_header.transaction_date,
    'currency', v_currency,
    'homeCurrency', v_home,
    'dueDate', v_header.due_date,
    'buyerReference', nullif(btrim(v_header.buyer_reference), ''),
    'contractReference', nullif(btrim(v_header.contract_reference), ''),
    'orderNumber', nullif(btrim(v_header.order_number), ''),
    'salesOrderReference', nullif(btrim(v_header.sales_order_reference), ''),
    'paymentTerms', nullif(btrim(v_header.payment_terms), ''),
    'notes', nullif(btrim(v_header.notes), ''),
    'supplyDate', v_header.supply_date,
    'periodStart', v_header.invoice_period_start,
    'periodEnd', v_header.invoice_period_end,
    'precedingReference', nullif(btrim(v_header.preceding_reference), ''),
    'precedingDate', v_header.preceding_date,
    'paymentMeans', nullif(btrim(v_header.payment_means_code), ''),
    'nett', v_header.foreign_nett_amount,
    'vat', v_header.foreign_vat_amount,
    'total', v_header.foreign_total_amount,
    'homeVat', v_header.home_vat_amount,
    'paid', v_header.paid_amount,
    'rounding', v_header.rounding_amount,
    'due', v_header.amount_due,
    'lineNettSum', v_line_nett,
    'breakdownVatSum', v_breakdown_vat,
    'seller', coalesce(v_seller, '{}'::jsonb),
    'buyer', coalesce(v_buyer, '{}'::jsonb),
    'lines', v_lines,
    'breakdown', v_breakdown
  );
end;
$$;


--
-- Name: finish_ai_action(text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_ai_action(p_token_hash text, p_ok boolean, p_summary text, p_detail text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.ai_actions
  set status = case when p_ok then 'confirmed' else 'failed' end,
      summary = coalesce(nullif(left(btrim(coalesce(p_summary, '')), 500), ''), summary),
      detail = nullif(left(btrim(coalesce(p_detail, '')), 500), '')
  where token_hash = p_token_hash
    and status = 'confirmed'
    and user_id = auth.uid();
end;
$$;


--
-- Name: grant_organisation_access(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_organisation_access(p_organisation_id uuid, p_email text, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  caller_role text;
  target_id uuid;
  target_role text;
  target_tenant uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in before granting access';
  end if;
  if p_role not in ('owner', 'admin', 'member') then
    raise exception 'Role must be owner, admin, or member';
  end if;

  caller_role := private.org_role(p_organisation_id);
  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'You need an owner or admin role in this organisation';
  end if;
  if caller_role = 'admin' and p_role <> 'member' then
    raise exception 'Could not grant access to that email address.';
  end if;

  select id into target_id
  from public.profiles
  where lower(email) = lower(btrim(p_email));

  if target_id is null then
    raise exception 'Could not grant access to that email address.';
  end if;

  select role into target_role
  from public.organisation_access
  where organisation_id = p_organisation_id
    and user_id = target_id;

  if caller_role = 'admin' and target_role in ('owner', 'admin') then
    raise exception 'Could not grant access to that email address.';
  end if;

  select tenant_id into target_tenant
  from public.organisations
  where id = p_organisation_id;

  insert into public.organisation_access (tenant_id, organisation_id, user_id, role)
  values (target_tenant, p_organisation_id, target_id, p_role)
  on conflict (organisation_id, user_id) do update
    set role = excluded.role;
end;
$$;


--
-- Name: import_e_document(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_e_document(p_id uuid, p_choices jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_doc public.e_documents%rowtype;
  v_type uuid;
  v_kind public.document_kind;
  v_currency uuid;
  v_rate numeric;
  v_supplier uuid := nullif(p_choices->>'supplierId', '')::uuid;
  v_supplier_currency uuid;
  v_code text;
  v_line jsonb;
  v_choice jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_vat uuid;
  v_vat_category text;
  v_vat_rate numeric;
  v_vat_type text;
  v_price numeric;
  v_base numeric;
  v_discount numeric;
  v_allowance jsonb;
  v_unsupported text;
  v_header uuid;
  v_payload jsonb;
begin
  select * into v_doc from public.e_documents where id = p_id;
  if v_doc.id is null or not private.is_org_member(v_doc.organisation_id) then
    raise exception 'That e-document was not found';
  end if;
  if v_doc.direction is distinct from 'inbound' or v_doc.status is distinct from 'valid' then
    raise exception 'Only a valid received e-invoice can be imported';
  end if;
  if v_doc.semantic is null then
    raise exception 'This e-invoice could not be read';
  end if;

  select string_agg(value, ', ') into v_unsupported
  from jsonb_array_elements_text(coalesce(v_doc.semantic->'_unsupported', '[]'::jsonb));
  if v_unsupported is not null then
    raise exception 'This e-invoice uses features Qula Plus cannot import yet: %', v_unsupported;
  end if;

  v_kind := case when v_doc.ubl_root = 'CreditNote' then 'credit_note'::public.document_kind else 'invoice'::public.document_kind end;
  v_type := nullif(p_choices->>'transactionTypeId', '')::uuid;
  if v_type is not null then
    if not exists (
      select 1 from public.transaction_types
      where id = v_type
        and organisation_id = v_doc.organisation_id
        and type = 'Purchases'
        and document_kind = v_kind
    ) then
      raise exception 'Choose a Purchases document type';
    end if;
  elsif v_kind = 'credit_note' then
    select inbound_credit_note_type_id into v_type
    from public.organisation_defaults where organisation_id = v_doc.organisation_id;
  else
    select inbound_invoice_type_id into v_type
    from public.organisation_defaults where organisation_id = v_doc.organisation_id;
  end if;
  if v_type is null then
    raise exception 'Choose a Purchases document type';
  end if;

  select id into v_currency
  from public.currencies
  where organisation_id = v_doc.organisation_id
    and (iso_code = v_doc.currency_code or code = v_doc.currency_code);
  if v_currency is null then
    raise exception 'Add the invoice currency to this organisation before importing';
  end if;
  select rate into v_rate from public.currencies where id = v_currency;

  if coalesce(p_choices->>'createSupplier', '') = 'true' then
    raise exception 'Create the supplier before importing';
  end if;

  if v_supplier is null then
    raise exception 'Choose a supplier';
  end if;
  select currency_id into v_supplier_currency
  from public.suppliers
  where id = v_supplier and organisation_id = v_doc.organisation_id;
  if v_supplier_currency is null then
    raise exception 'Choose a supplier from this organisation';
  end if;
  if v_supplier_currency is distinct from v_currency then
    raise exception 'The supplier currency must match the e-invoice currency';
  end if;

  for v_line in
    select value from jsonb_array_elements(coalesce(v_doc.semantic->'BG-25', '[]'::jsonb))
  loop
    select value into v_choice
    from jsonb_array_elements(coalesce(p_choices->'lines', '[]'::jsonb)) as value
    where value->>'lineNumber' = v_line->>'BT-126'
    limit 1;

    v_vat := nullif(v_choice->>'vatRateId', '')::uuid;
    if v_vat is null then
      raise exception 'Choose an Expense VAT rate for each line';
    end if;
    select vat_category, rate, vat_type into v_vat_category, v_vat_rate, v_vat_type
    from public.vat_rates
    where id = v_vat and organisation_id = v_doc.organisation_id;
    if v_vat_type is distinct from 'Expense'
       or v_vat_category is distinct from nullif(v_line #>> '{BG-30,BT-151}', '')
       or v_vat_rate is distinct from nullif(v_line #>> '{BG-30,BT-152}', '')::numeric then
      raise exception 'Choose an Expense VAT rate that matches the e-invoice category and percentage';
    end if;

    v_price := nullif(v_line #>> '{BG-29,BT-146}', '')::numeric;
    v_base := nullif(v_line #>> '{BG-29,BT-149}', '')::numeric;
    if v_base is not null and v_base <> 0 and v_price is not null then
      v_price := v_price / v_base;
    end if;
    v_discount := 0;
    for v_allowance in
      select value from jsonb_array_elements(coalesce(v_line->'BG-27', '[]'::jsonb))
    loop
      if coalesce(v_allowance->>'charge', '') = 'true' then
        raise exception 'This e-invoice uses features Qula Plus cannot import yet: line charge';
      end if;
      v_discount := v_discount + coalesce(nullif(v_allowance->>'BT-136', '')::numeric, 0);
    end loop;

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'description', coalesce(nullif(v_line #>> '{BG-31,BT-153}', ''), 'Item'),
      'quantity', coalesce(v_line->>'BT-129', '1'),
      'price', coalesce(v_price, 0),
      'discountAmount', v_discount,
      'unitCode', coalesce(nullif(v_line->>'BT-130', ''), 'C62'),
      'vatRateId', v_vat,
      'glCodeId', nullif(v_choice->>'glCodeId', ''),
      'departmentId', nullif(v_choice->>'departmentId', ''),
      'costCentreId', nullif(v_choice->>'costCentreId', ''),
      'sellerItemId', nullif(v_line #>> '{BG-31,BT-155}', ''),
      'lineNote', nullif(v_line->>'BT-127', '')
    ));
  end loop;

  v_payload := jsonb_build_object(
    'transactionTypeId', v_type,
    'transactionDate', v_doc.issue_date,
    'dueDate', nullif(v_doc.semantic->>'BT-9', ''),
    'supplierId', v_supplier,
    'partyName', coalesce(v_doc.seller_name, 'Supplier'),
    'currencyId', v_currency,
    'exchangeRate', v_rate,
    'orderNumber', nullif(v_doc.semantic->>'BT-13', ''),
    'supplierReference', v_doc.document_number,
    'precedingReference', nullif(v_doc.semantic #>> '{BG-3,BT-25}', ''),
    'precedingDate', nullif(v_doc.semantic #>> '{BG-3,BT-26}', ''),
    'buyerReference', nullif(v_doc.semantic->>'BT-10', ''),
    'contractReference', nullif(v_doc.semantic->>'BT-12', ''),
    'paymentTerms', nullif(v_doc.semantic->>'BT-20', ''),
    'notes', nullif(v_doc.semantic->>'BT-22', ''),
    'invoicePeriodStart', nullif(v_doc.semantic #>> '{BG-14,BT-73}', ''),
    'invoicePeriodEnd', nullif(v_doc.semantic #>> '{BG-14,BT-74}', ''),
    'lines', v_lines
  );

  begin
    v_header := public.save_document(v_payload);
  exception
    when unique_violation then
      raise exception 'This supplier invoice number is already used on another document';
  end;

  perform private.set_e_document_status(p_id, 'imported', jsonb_build_object('headerId', v_header));
  return v_header;
end;
$$;


--
-- Name: organisation_secret_ciphertext(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organisation_secret_ciphertext(p_organisation_id uuid, p_kind text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_value text;
begin
  if not private.is_org_member(p_organisation_id) then
    raise exception 'That organisation was not found';
  end if;
  select ciphertext into v_value
  from public.organisation_secrets
  where organisation_id = p_organisation_id and kind = p_kind;
  return v_value;
end;
$$;


--
-- Name: organisation_secret_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organisation_secret_status(p_organisation_id uuid) RETURNS TABLE(kind text, hint text, updated_at timestamp with time zone, updated_by uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_org_member(p_organisation_id) then
    raise exception 'That organisation was not found';
  end if;
  return query
    select secrets.kind, secrets.hint, secrets.updated_at, secrets.updated_by
    from public.organisation_secrets as secrets
    where secrets.organisation_id = p_organisation_id;
end;
$$;


--
-- Name: post_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_document(p_header_id uuid, p_logo_path text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_status public.document_status;
  v_date date;
  v_supplier uuid;
  v_type uuid;
  v_reference integer;
  v_numbering public.numbering_rule;
  v_direction text;
  v_lines integer;
  v_issuer jsonb;
  v_party jsonb;
  v_iban text;
  v_customer uuid;
  v_errors text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in before posting a document';
  end if;

  select organisation_id, status, transaction_date, supplier_id, customer_id, transaction_type_id, reference
    into v_org, v_status, v_date, v_supplier, v_customer, v_type, v_reference
  from public.transaction_headers
  where id = p_header_id
  for update;

  if v_org is null then
    raise exception 'That document could not be posted';
  end if;
  if not (select private.is_org_member(v_org)) then
    raise exception 'You are not a member of this organisation';
  end if;
  if v_status is distinct from 'draft' then
    raise exception 'Only a draft document can be posted';
  end if;
  if private.document_period_locked(v_org, v_date) then
    raise exception 'This date is in a locked period';
  end if;
  if p_logo_path is not null
     and p_logo_path is distinct from v_org::text || '/snapshots/' || p_header_id::text then
    raise exception 'The posted logo path is not valid';
  end if;

  select count(*) into v_lines
  from public.transaction_lines
  where header_id = p_header_id;

  if v_lines < 1 then
    raise exception 'Add a line before posting';
  end if;

  select numbering, type into v_numbering, v_direction
  from public.transaction_types
  where id = v_type;

  if v_numbering = 'on_post' and v_reference is null then
    perform 1
    from public.transaction_types
    where id = v_type
    for update;
  end if;

  select defaults.iban into v_iban
  from public.organisation_defaults as defaults
  where defaults.organisation_id = v_org;

  if v_direction = 'Sales' and v_iban is not null then
    update public.transaction_headers
    set payment_means_code = '58'
    where id = p_header_id
      and payment_means_code is null;
  end if;

  if v_direction = 'Sales' then
    select string_agg(format('%s: %s', ready.rule_id, ready.message), ' ' order by ready.rule_id)
      into v_errors
    from public.en16931_readiness(p_header_id) as ready
    where ready.severity = 'error';
    if v_errors is not null then
      raise exception 'This sales document is not ready to post. %', v_errors;
    end if;
  end if;

  if v_numbering = 'on_post' and v_reference is null then
    v_reference := private.issue_reference(v_type);
  end if;

  select jsonb_build_object(
    'name', organisation.name,
    'address', private.postal_address_text(
      defaults.address_line1, defaults.address_line2, defaults.address_line3,
      defaults.city, defaults.post_code, defaults.county, seller_country.name
    ),
    'addressLine1', defaults.address_line1,
    'addressLine2', defaults.address_line2,
    'addressLine3', defaults.address_line3,
    'city', defaults.city,
    'postCode', defaults.post_code,
    'county', defaults.county,
    'countryCode', defaults.country_code,
    'countryName', seller_country.name,
    'contactName', defaults.contact_name,
    'contactEmail', defaults.contact_email,
    'website', defaults.website,
    'phone', defaults.phone,
    'vatNumber', defaults.vat_number,
    'companyNumber', defaults.company_number,
    'peppolScheme', defaults.peppol_scheme,
    'peppolId', defaults.peppol_id,
    'iban', defaults.iban,
    'bic', defaults.bic,
    'bankAccountName', defaults.bank_account_name,
    'bankingDetails', defaults.banking_details,
    'logoPath', p_logo_path
  )
  into v_issuer
  from public.organisations as organisation
  left join public.organisation_defaults as defaults
    on defaults.organisation_id = organisation.id
  left join public.ref_countries as seller_country
    on seller_country.code = defaults.country_code
  where organisation.id = v_org;

  if v_direction = 'Sales' then
    select jsonb_build_object(
      'code', customers.code,
      'name', customers.name,
      'address', private.postal_address_text(
        customers.address_line1, customers.address_line2, customers.address_line3,
        customers.city, customers.post_code, customers.county, party_country.name
      ),
      'addressLine1', customers.address_line1,
      'addressLine2', customers.address_line2,
      'addressLine3', customers.address_line3,
      'city', customers.city,
      'postCode', customers.post_code,
      'county', customers.county,
      'countryCode', customers.country_code,
      'countryName', party_country.name,
      'phone', customers.phone,
      'email', customers.email,
      'website', customers.website,
      'contactDetails', customers.contact_details,
      'vatNumber', customers.vat_number,
      'companyNumber', customers.company_number,
      'peppolScheme', customers.peppol_scheme,
      'peppolId', customers.peppol_id
    )
    into v_party
    from public.customers as customers
    left join public.ref_countries as party_country
      on party_country.code = customers.country_code
    where customers.id = v_customer;
  else
  select jsonb_build_object(
    'code', supplier.code,
    'name', supplier.name,
    'address', private.postal_address_text(
      supplier.address_line1, supplier.address_line2, supplier.address_line3,
      supplier.city, supplier.post_code, supplier.county, party_country.name
    ),
    'addressLine1', supplier.address_line1,
    'addressLine2', supplier.address_line2,
    'addressLine3', supplier.address_line3,
    'city', supplier.city,
    'postCode', supplier.post_code,
    'county', supplier.county,
    'countryCode', supplier.country_code,
    'countryName', party_country.name,
    'phone', supplier.phone,
    'email', supplier.email,
    'website', supplier.website,
    'contactDetails', supplier.contact_details,
    'vatNumber', supplier.vat_number,
    'companyNumber', supplier.company_number,
    'peppolScheme', supplier.peppol_scheme,
    'peppolId', supplier.peppol_id
  )
  into v_party
  from public.suppliers as supplier
  left join public.ref_countries as party_country
    on party_country.code = supplier.country_code
  where supplier.id = v_supplier;
  end if;

  perform set_config('fintran.status_change', 'on', true);
  update public.transaction_headers
  set status = 'posted',
      posted_at = now(),
      posted_by = (select auth.uid()),
      issuer_snapshot = v_issuer,
      party_snapshot = v_party,
      reference = v_reference
  where id = p_header_id;
  perform set_config('fintran.status_change', 'off', true);
end;
$$;


--
-- Name: propose_ai_action(uuid, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_ai_action(p_organisation_id uuid, p_action text, p_token_hash text, p_target_id uuid, p_summary text, p_proposal jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user uuid := auth.uid();
  v_tenant uuid;
  v_version timestamptz;
  v_status text;
  v_id uuid;
begin
  if v_user is null or not private.is_org_member(p_organisation_id) then
    raise exception 'That organisation was not found';
  end if;
  if not exists (
    select 1 from public.ai_settings
    where organisation_id = p_organisation_id and enabled and actions_enabled
  ) then
    raise exception 'Ask Qula actions are switched off for this organisation';
  end if;
  if p_action not in ('post_draft', 'add_party') then
    raise exception 'That action is not recognised';
  end if;
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'That action could not be proposed';
  end if;
  if p_action = 'post_draft' then
    select status::text, updated_at into v_status, v_version
    from public.transaction_headers
    where id = p_target_id and organisation_id = p_organisation_id;
    if v_status is null then
      raise exception 'That document could not be found';
    end if;
    if v_status <> 'draft' then
      raise exception 'Only a draft can be posted';
    end if;
  elsif p_target_id is not null then
    raise exception 'That action could not be proposed';
  end if;
  select tenant_id into v_tenant from public.organisations where id = p_organisation_id;

  -- Anything this person left unanswered has run out, or is replaced by this newer proposal for the same thing.
  update public.ai_actions
  set status = 'expired', decided_at = now()
  where organisation_id = p_organisation_id and user_id = v_user and status = 'proposed' and expires_at <= now();
  update public.ai_actions
  set status = 'superseded', decided_at = now()
  where organisation_id = p_organisation_id and user_id = v_user and status = 'proposed'
    and action = p_action and target_id is not distinct from p_target_id;

  insert into public.ai_actions (
    organisation_id, tenant_id, user_id, action, summary, status, token_hash, expires_at, target_id, target_version, proposal
  ) values (
    p_organisation_id, v_tenant, v_user, p_action,
    left(btrim(coalesce(nullif(btrim(p_summary), ''), p_action)), 500),
    'proposed', p_token_hash, now() + interval '10 minutes', p_target_id, v_version, coalesce(p_proposal, '{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$_$;


--
-- Name: record_ai_feedback(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_ai_feedback(p_organisation_id uuid, p_rating integer, p_question text, p_answer text, p_comment text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant uuid;
  v_provider text;
  v_model text;
  v_log boolean;
begin
  if not private.is_org_member(p_organisation_id) then
    raise exception 'That organisation was not found';
  end if;
  if p_rating not in (-1, 1) then
    raise exception 'The rating must be thumbs up or thumbs down';
  end if;
  select tenant_id into v_tenant from public.organisations where id = p_organisation_id;
  select provider_code, model, log_answers into v_provider, v_model, v_log
  from public.ai_settings where organisation_id = p_organisation_id;
  insert into public.ai_feedback (
    organisation_id, tenant_id, user_id, rating, provider_code, model, comment, question, answer
  ) values (
    p_organisation_id, v_tenant, auth.uid(), p_rating, v_provider, v_model,
    nullif(left(btrim(coalesce(p_comment, '')), 500), ''),
    case when coalesce(v_log, false) then nullif(left(btrim(coalesce(p_question, '')), 1000), '') end,
    case when coalesce(v_log, false) then nullif(left(btrim(coalesce(p_answer, '')), 4000), '') end
  );
end;
$$;


--
-- Name: record_ai_usage(uuid, text, text, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_ai_usage(p_organisation_id uuid, p_provider_code text, p_model text, p_input_tokens integer, p_output_tokens integer, p_tool_calls integer, p_outcome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_org_member(p_organisation_id) then
    raise exception 'That organisation was not found';
  end if;
  if p_outcome not in ('ok', 'error', 'limited', 'fallback') then
    raise exception 'That usage outcome is not recognised';
  end if;
  insert into public.ai_usage (
    organisation_id, tenant_id, user_id, provider_code, model,
    input_tokens, output_tokens, tool_calls, outcome
  )
  select p_organisation_id, tenant_id, auth.uid(), p_provider_code, p_model,
    coalesce(p_input_tokens, 0), coalesce(p_output_tokens, 0), coalesce(p_tool_calls, 0), p_outcome
  from public.organisations where id = p_organisation_id;
end;
$$;


--
-- Name: reject_e_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_e_document(p_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_direction public.e_document_direction;
begin
  if nullif(btrim(p_reason), '') is null then
    raise exception 'A rejection needs a reason';
  end if;
  select organisation_id, direction into v_org, v_direction
  from public.e_documents where id = p_id;
  if v_org is null or not private.is_org_member(v_org) then
    raise exception 'That e-document was not found';
  end if;
  if not private.has_org_role(v_org, array['owner', 'admin']) then
    raise exception 'Only an owner or admin can reject an e-invoice';
  end if;
  if v_direction is distinct from 'inbound' then
    raise exception 'Only a received e-invoice can be rejected';
  end if;
  perform private.set_e_document_status(p_id, 'rejected', jsonb_build_object('reason', btrim(p_reason)));
end;
$$;


--
-- Name: release_duplicate_e_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_duplicate_e_document(p_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_status public.e_document_status;
begin
  if nullif(btrim(p_reason), '') is null then
    raise exception 'A release needs a reason';
  end if;
  select organisation_id, status into v_org, v_status from public.e_documents where id = p_id;
  if v_org is null or not private.is_org_member(v_org) then
    raise exception 'That e-document was not found';
  end if;
  if not private.has_org_role(v_org, array['owner', 'admin']) then
    raise exception 'Only an owner or admin can release a duplicate';
  end if;
  if v_status is distinct from 'duplicate' then
    raise exception 'Only a duplicate e-invoice can be released';
  end if;
  perform private.set_e_document_status(p_id, 'valid', jsonb_build_object('reason', btrim(p_reason)));
end;
$$;


--
-- Name: rename_organisation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_organisation(p_organisation_id uuid, p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in before renaming an organisation';
  end if;
  if not (select private.has_org_role(p_organisation_id, array['owner', 'admin'])) then
    raise exception 'You need an owner or admin role to rename an organisation';
  end if;
  if char_length(btrim(p_name)) < 2 or char_length(btrim(p_name)) > 80 then
    raise exception 'Organisation name must be between 2 and 80 characters';
  end if;

  update public.organisations
  set name = btrim(p_name)
  where id = p_organisation_id;

  if not found then
    raise exception 'That organisation could not be renamed';
  end if;
end;
$$;


--
-- Name: revoke_organisation_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_organisation_access(p_organisation_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  caller_role text;
  target_role text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in before changing access';
  end if;

  caller_role := private.org_role(p_organisation_id);
  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'You need an owner or admin role in this organisation';
  end if;

  select role into target_role
  from public.organisation_access
  where organisation_id = p_organisation_id
    and user_id = p_user_id;

  if target_role is null then
    raise exception 'That user does not have access to this organisation';
  end if;
  if caller_role = 'admin' and target_role <> 'member' then
    raise exception 'You can only remove a member';
  end if;

  delete from public.organisation_access
  where organisation_id = p_organisation_id
    and user_id = p_user_id;
end;
$$;


--
-- Name: save_document(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_document(p_document jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_tenant uuid;
  v_direction text;
  v_header_id uuid;
  v_header_org uuid;
  v_party_name text;
  v_party_currency uuid;
  v_currency uuid;
  v_line jsonb;
  v_line_number integer := 0;
  v_status public.document_status;
  v_product_id uuid;
  v_purchase_price numeric;
  v_sales_price numeric;
  v_purchase_gl uuid;
  v_sales_gl uuid;
  v_purchase_vat uuid;
  v_sales_vat uuid;
  v_unit text;
  v_price numeric;
  v_gl uuid;
  v_vat uuid;
  v_line_unit text;
begin
  select organisation_id, tenant_id, type
    into v_org, v_tenant, v_direction
  from public.transaction_types
  where id = nullif(p_document->>'transactionTypeId', '')::uuid;
  if v_org is null or v_direction not in ('Sales', 'Purchases') then
    raise exception 'Choose a transaction type';
  end if;
  if v_direction = 'Sales' and nullif(p_document->>'supplierId', '') is not null then
    raise exception 'A sales document cannot have a supplier';
  end if;
  if v_direction = 'Purchases' and nullif(p_document->>'customerId', '') is not null then
    raise exception 'A purchase document cannot have a customer';
  end if;
  if v_direction = 'Sales' then
    select name, currency_id into v_party_name, v_party_currency
    from public.customers
    where id = nullif(p_document->>'customerId', '')::uuid
      and organisation_id = v_org;
    if v_party_name is null then
      raise exception 'Choose a customer';
    end if;
  else
    select name, currency_id into v_party_name, v_party_currency
    from public.suppliers
    where id = nullif(p_document->>'supplierId', '')::uuid
      and organisation_id = v_org;
    if v_party_name is null then
      raise exception 'Choose a supplier';
    end if;
  end if;
  if nullif(btrim(p_document->>'partyName'), '') is not null then
    v_party_name := btrim(p_document->>'partyName');
  elsif nullif(btrim(p_document->>'supplierName'), '') is not null then
    v_party_name := btrim(p_document->>'supplierName');
  end if;
  if coalesce(nullif(p_document->>'paidAmount', '')::numeric, 0)
       is distinct from round(coalesce(nullif(p_document->>'paidAmount', '')::numeric, 0), 2) then
    raise exception 'Amounts can have at most 2 decimal places.';
  end if;
  v_currency := nullif(p_document->>'currencyId', '')::uuid;
  if v_currency is null then
    v_currency := v_party_currency;
  end if;
  v_header_id := nullif(p_document->>'id', '')::uuid;
  if v_header_id is null then
    insert into public.transaction_headers (
      tenant_id, organisation_id, transaction_type_id, reference,
      transaction_date, due_date, supplier_id, customer_id, party_name, contact_details, notes,
      currency_id, exchange_rate, order_number, sales_order_reference, paid_amount, rounding_amount,
      supplier_reference, supply_date,
      preceding_header_id, preceding_reference, preceding_date,
      buyer_reference, contract_reference, payment_terms,
      invoice_period_start, invoice_period_end, payment_means_code,
      flex1, flex2, flex3, flex4, flex5
    ) values (
      v_tenant, v_org, (p_document->>'transactionTypeId')::uuid, 0,
      (p_document->>'transactionDate')::date,
      nullif(p_document->>'dueDate', '')::date,
      nullif(p_document->>'supplierId', '')::uuid,
      nullif(p_document->>'customerId', '')::uuid,
      v_party_name, p_document->>'contactDetails', p_document->>'notes', v_currency,
      (p_document->>'exchangeRate')::numeric, p_document->>'orderNumber', nullif(btrim(p_document->>'salesOrderReference'), ''),
      coalesce(nullif(p_document->>'paidAmount', '')::numeric, 0),
      coalesce(nullif(p_document->>'roundingAmount', '')::numeric, 0),
      p_document->>'supplierReference', nullif(p_document->>'supplyDate', '')::date,
      nullif(p_document->>'precedingHeaderId', '')::uuid,
      nullif(p_document->>'precedingReference', ''),
      nullif(p_document->>'precedingDate', '')::date,
      nullif(p_document->>'buyerReference', ''),
      nullif(p_document->>'contractReference', ''),
      nullif(p_document->>'paymentTerms', ''),
      nullif(p_document->>'invoicePeriodStart', '')::date,
      nullif(p_document->>'invoicePeriodEnd', '')::date,
      nullif(p_document->>'paymentMeansCode', ''),
      p_document->>'flex1', p_document->>'flex2', p_document->>'flex3', p_document->>'flex4', p_document->>'flex5'
    ) returning id into v_header_id;
  else
    select organisation_id, status into v_header_org, v_status
    from public.transaction_headers where id = v_header_id;
    if v_header_org is null then raise exception 'That invoice could not be updated'; end if;
    if v_status::text not in ('draft', 'open') then raise exception 'Only a draft document or an active order can be changed'; end if;
    if v_header_org is distinct from v_org then raise exception 'That invoice belongs to another organisation'; end if;
    if not exists (select 1 from public.organisation_access where organisation_id = v_header_org and user_id = (select auth.uid())) then
      raise exception 'You are not a member of this organisation';
    end if;
    update public.transaction_headers set
      transaction_date = (p_document->>'transactionDate')::date,
      due_date = nullif(p_document->>'dueDate', '')::date,
      supplier_id = nullif(p_document->>'supplierId', '')::uuid,
      customer_id = nullif(p_document->>'customerId', '')::uuid,
      party_name = v_party_name,
      contact_details = p_document->>'contactDetails',
      notes = p_document->>'notes',
      currency_id = v_currency,
      exchange_rate = (p_document->>'exchangeRate')::numeric,
      order_number = p_document->>'orderNumber',
      sales_order_reference = nullif(btrim(p_document->>'salesOrderReference'), ''),
      paid_amount = coalesce(nullif(p_document->>'paidAmount', '')::numeric, 0),
      rounding_amount = coalesce(nullif(p_document->>'roundingAmount', '')::numeric, 0),
      supplier_reference = p_document->>'supplierReference',
      supply_date = nullif(p_document->>'supplyDate', '')::date,
      preceding_header_id = nullif(p_document->>'precedingHeaderId', '')::uuid,
      preceding_reference = nullif(p_document->>'precedingReference', ''),
      preceding_date = nullif(p_document->>'precedingDate', '')::date,
      buyer_reference = nullif(p_document->>'buyerReference', ''),
      contract_reference = nullif(p_document->>'contractReference', ''),
      payment_terms = nullif(p_document->>'paymentTerms', ''),
      invoice_period_start = nullif(p_document->>'invoicePeriodStart', '')::date,
      invoice_period_end = nullif(p_document->>'invoicePeriodEnd', '')::date,
      payment_means_code = nullif(p_document->>'paymentMeansCode', ''),
      flex1 = p_document->>'flex1', flex2 = p_document->>'flex2', flex3 = p_document->>'flex3',
      flex4 = p_document->>'flex4', flex5 = p_document->>'flex5'
    where id = v_header_id and organisation_id = v_org;
    if not found then raise exception 'That invoice could not be updated'; end if;
    delete from public.transaction_lines where header_id = v_header_id;
  end if;
  for v_line in select value from jsonb_array_elements(coalesce(p_document->'lines', '[]'::jsonb))
  loop
    v_line_number := v_line_number + 1;
    if coalesce(nullif(v_line->>'discountAmount', '')::numeric, 0)
         is distinct from round(coalesce(nullif(v_line->>'discountAmount', '')::numeric, 0), 2) then
      raise exception 'Amounts can have at most 2 decimal places.';
    end if;
    v_product_id := nullif(v_line->>'productId', '')::uuid;
    v_price := nullif(v_line->>'price', '')::numeric;
    v_gl := nullif(v_line->>'glCodeId', '')::uuid;
    v_vat := nullif(v_line->>'vatRateId', '')::uuid;
    v_line_unit := nullif(v_line->>'unitCode', '');
    if v_product_id is not null then
      select purchase_price, sales_price, purchase_gl_code_id, sales_gl_code_id,
             purchase_vat_code_id, sales_vat_code_id, unit_code
        into v_purchase_price, v_sales_price, v_purchase_gl, v_sales_gl,
             v_purchase_vat, v_sales_vat, v_unit
      from public.products where id = v_product_id and organisation_id = v_org;
      if not found then raise exception 'Choose a product from this organisation'; end if;
      if v_direction = 'Sales' then
        if v_price is null then v_price := v_sales_price; end if;
        if v_gl is null then v_gl := v_sales_gl; end if;
        if v_vat is null then v_vat := v_sales_vat; end if;
      else
        if v_price is null then v_price := v_purchase_price; end if;
        if v_gl is null then v_gl := v_purchase_gl; end if;
        if v_vat is null then v_vat := v_purchase_vat; end if;
      end if;
      if v_line_unit is null then v_line_unit := v_unit; end if;
    end if;
    insert into public.transaction_lines (
      id, source_line_id, tenant_id, organisation_id, header_id, transaction_type_id, line_number,
      product_id, description, gl_code_id, department_id, cost_centre_id, vat_rate_id,
      quantity, price, discount_amount, nett_amount, vat_amount,
      unit_code, line_note, seller_item_id, order_line_reference,
      credited_line_id, returns_to_order
    ) values (
      coalesce(nullif(v_line->>'id', '')::uuid, gen_random_uuid()), nullif(v_line->>'sourceLineId', '')::uuid,
      v_tenant, v_org, v_header_id, (p_document->>'transactionTypeId')::uuid, v_line_number,
      v_product_id, coalesce(v_line->>'description', ''), v_gl,
      nullif(v_line->>'departmentId', '')::uuid, nullif(v_line->>'costCentreId', '')::uuid, v_vat,
      coalesce(nullif(v_line->>'quantity', '')::numeric, 0), coalesce(v_price, 0),
      coalesce(nullif(v_line->>'discountAmount', '')::numeric, 0), 0, 0,
      v_line_unit, nullif(v_line->>'lineNote', ''), nullif(v_line->>'sellerItemId', ''),
      nullif(btrim(v_line->>'orderLineReference'), ''),
      nullif(v_line->>'creditedLineId', '')::uuid, coalesce(nullif(v_line->>'returnsToOrder', '')::boolean, false)
    );
  end loop;
  -- A line that another document draws on cannot be removed.
  set constraints public.transaction_lines_source_line_id_fkey immediate;
  set constraints public.transaction_lines_source_line_id_fkey deferred;
  return v_header_id;
end;
$$;


--
-- Name: set_order_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_status(p_header_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_status text;
  v_type uuid;
  v_reference integer;
  v_kind text;
  v_numbering public.numbering_rule;
  v_lines integer;
  v_next public.document_status;
begin
  if (select auth.uid()) is null then raise exception 'Sign in before changing an order'; end if;
  select organisation_id, status::text, transaction_type_id, reference
    into v_org, v_status, v_type, v_reference
  from public.transaction_headers where id = p_header_id for update;
  if v_org is null then raise exception 'That order was not found'; end if;
  if not (select private.is_org_member(v_org)) then raise exception 'You are not a member of this organisation'; end if;
  select document_kind::text, numbering into v_kind, v_numbering from public.transaction_types where id = v_type;
  if v_kind is null or v_kind not in ('order', 'requisition') then
    raise exception 'Only an order or a requisition can be activated and closed';
  end if;

  if p_action = 'open' then
    if v_status <> 'draft' then raise exception 'Only a draft order can be activated'; end if;
    select count(*) into v_lines from public.transaction_lines where header_id = p_header_id;
    if v_lines < 1 then raise exception 'Add a line before activating'; end if;
    if v_numbering = 'on_post' and v_reference is null then v_reference := private.issue_reference(v_type); end if;
    v_next := 'open';
  elsif p_action = 'close' then
    if v_status <> 'open' then raise exception 'Only an active order can be closed'; end if;
    v_next := 'closed';
  elsif p_action = 'reopen' then
    if v_status <> 'closed' then raise exception 'Only a closed order can be reopened'; end if;
    v_next := 'open';
  elsif p_action = 'cancel' then
    if v_status <> 'open' then raise exception 'Only an active order can be cancelled'; end if;
    if exists (
      select 1
      from public.transaction_lines as line
      join public.transaction_lines as drawn on drawn.source_line_id = line.id
      join public.transaction_headers as header on header.id = drawn.header_id
      where line.header_id = p_header_id and header.status <> 'void'
    ) then
      raise exception 'Another document has been created from this one, so it cannot be cancelled. Close it instead.';
    end if;
    v_next := 'cancelled';
  else
    raise exception 'That order action is not recognised';
  end if;

  perform set_config('fintran.status_change', 'on', true);
  -- A change made by a person is never a system close, so a later void leaves a hand-closed order closed.
  update public.transaction_headers set status = v_next, reference = v_reference, closed_by_system = false where id = p_header_id;
  perform set_config('fintran.status_change', 'off', true);
end;
$$;


--
-- Name: set_organisation_secret(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_organisation_secret(p_organisation_id uuid, p_kind text, p_ciphertext text, p_hint text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.has_org_role(p_organisation_id, array['owner', 'admin']) then
    raise exception 'Only an owner or admin can store a secret';
  end if;
  if p_kind not in ('ai_api_key', 'ap_api_key', 'ap_webhook_secret') then
    raise exception 'That secret is not recognised';
  end if;
  insert into public.organisation_secrets (
    organisation_id, tenant_id, kind, ciphertext, hint, created_by, updated_by
  )
  select p_organisation_id, tenant_id, p_kind, p_ciphertext, nullif(p_hint, ''), auth.uid(), auth.uid()
  from public.organisations where id = p_organisation_id
  on conflict (organisation_id, kind) do update
    set ciphertext = excluded.ciphertext,
        hint = excluded.hint,
        updated_at = now(),
        updated_by = auth.uid();
  insert into public.audit_log (table_name, row_id, action, new_values, changed_by, tenant_id, organisation_id)
  select 'organisation_secrets', p_organisation_id::text, 'UPDATE',
    jsonb_build_object('kind', p_kind, 'hint', nullif(p_hint, '')),
    auth.uid(), tenant_id, id
  from public.organisations where id = p_organisation_id;
end;
$$;


--
-- Name: store_e_document(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_e_document(p_envelope jsonb, p_signature text, p_xml text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_key_id text := p_envelope->>'keyId';
  v_issued timestamptz := nullif(p_envelope->>'issuedAt', '')::timestamptz;
  v_org uuid := nullif(p_envelope->>'organisationId', '')::uuid;
  v_direction public.e_document_direction := nullif(p_envelope->>'direction', '')::public.e_document_direction;
  v_source text := p_envelope->>'source';
  v_header uuid := nullif(p_envelope->>'headerId', '')::uuid;
  v_sha text := p_envelope->>'sha256';
  v_size integer := nullif(p_envelope->>'byteSize', '')::integer;
  v_summary jsonb := coalesce(p_envelope->'summary', '{}'::jsonb);
  v_semantic jsonb := p_envelope->'semantic';
  v_validation jsonb := coalesce(p_envelope->'validation', '{}'::jsonb);
  v_expected text;
  v_existing uuid;
  v_id uuid;
  v_tenant uuid;
  v_scheme text;
  v_peppol text;
  v_vat text;
  v_status public.e_document_status;
  v_duplicate uuid;
  v_fatal boolean;
  v_header_status public.document_status;
  v_header_kind public.document_kind;
  v_header_type text;
  v_result jsonb;
begin
  if v_org is null or not private.is_org_member(v_org) then
    raise exception 'You are not a member of this organisation';
  end if;
  if v_issued is null or v_issued < now() - interval '10 minutes' or v_issued > now() + interval '2 minutes' then
    raise exception 'The envelope has expired';
  end if;
  if v_direction is null or v_source not in ('generated', 'manual_upload') then
    raise exception 'The envelope is not valid';
  end if;
  if v_sha is null or v_sha !~ '^[0-9a-f]{64}$' then
    raise exception 'The envelope is not valid';
  end if;
  if p_xml is null or octet_length(convert_to(p_xml, 'utf8')) > 4194304 or octet_length(convert_to(p_xml, 'utf8')) <> v_size then
    raise exception 'The e-document file is too large';
  end if;

  v_expected := private.einvoice_signature(v_key_id, p_envelope);
  if not private.signatures_match(lower(p_signature), v_expected) then
    raise exception 'The envelope signature does not match';
  end if;
  if encode(extensions.digest(convert_to(p_xml, 'utf8'), 'sha256'), 'hex') is distinct from v_sha then
    raise exception 'The e-document file does not match its recorded hash';
  end if;

  if v_direction = 'inbound' then
    select id into v_existing
    from public.e_documents
    where organisation_id = v_org and direction = 'inbound' and sha256 = v_sha;
    if v_existing is not null then
      return v_existing;
    end if;

    select peppol_scheme, peppol_id, vat_number
      into v_scheme, v_peppol, v_vat
    from public.organisation_defaults
    where organisation_id = v_org;

    if v_scheme is not null and v_peppol is not null then
      if v_summary->>'receiverScheme' is distinct from v_scheme
         or lower(coalesce(v_summary->>'receiverId', '')) is distinct from lower(v_peppol) then
        raise exception 'This e-invoice is addressed to a different organisation';
      end if;
    elsif v_vat is not null then
      if lower(coalesce(v_summary->>'buyerVat', '')) is distinct from lower(v_vat) then
        raise exception 'This e-invoice is addressed to a different organisation';
      end if;
    else
      raise exception 'Set a Peppol ID or VAT number before receiving an e-invoice';
    end if;
  else
    select header.status, kind.document_kind, kind.type
      into v_header_status, v_header_kind, v_header_type
    from public.transaction_headers as header
    join public.transaction_types as kind on kind.id = header.transaction_type_id
    where header.id = v_header and header.organisation_id = v_org;

    if v_header_status is distinct from 'posted'
       or v_header_type is distinct from 'Sales'
       or v_header_kind not in ('invoice', 'credit_note') then
      raise exception 'An outbound e-invoice needs a posted sales invoice or credit note';
    end if;
    if v_semantic is distinct from public.en16931_document(v_header) then
      raise exception 'The e-invoice does not match the posted document';
    end if;
    if exists (
      select 1 from public.e_documents
      where header_id = v_header and direction = 'outbound' and status = 'valid'
    ) then
      raise exception 'This document already has a valid e-invoice';
    end if;
  end if;

  select tenant_id into v_tenant from public.organisations where id = v_org;
  v_fatal := exists (
    select 1 from jsonb_array_elements(coalesce(v_validation->'results', '[]'::jsonb)) as item
    where item->>'severity' = 'fatal'
  );

  insert into public.e_documents (
    tenant_id, organisation_id, direction, status, source, ubl_root,
    customization_id, profile_id, header_id, sha256, byte_size,
    sender_scheme, sender_id, receiver_scheme, receiver_id,
    document_number, issue_date, currency_code, total_amount, amount_due,
    seller_name, seller_vat_number, buyer_name, buyer_vat_number,
    semantic, validator_version, rules_version, created_by, updated_by
  ) values (
    v_tenant,
    v_org,
    v_direction,
    case when v_direction = 'outbound' then 'generated'::public.e_document_status else 'received'::public.e_document_status end,
    v_source,
    v_summary->>'ublRoot',
    nullif(v_summary->>'customizationId', ''),
    nullif(v_summary->>'profileId', ''),
    v_header,
    v_sha,
    v_size,
    nullif(v_summary->>'senderScheme', ''),
    nullif(v_summary->>'senderId', ''),
    nullif(v_summary->>'receiverScheme', ''),
    nullif(v_summary->>'receiverId', ''),
    nullif(v_summary->>'documentNumber', ''),
    nullif(v_summary->>'issueDate', '')::date,
    nullif(v_summary->>'currencyCode', ''),
    nullif(v_summary->>'totalAmount', '')::numeric,
    nullif(v_summary->>'amountDue', '')::numeric,
    nullif(v_summary->>'sellerName', ''),
    nullif(v_summary->>'sellerVat', ''),
    nullif(v_summary->>'buyerName', ''),
    nullif(v_summary->>'buyerVat', ''),
    v_semantic,
    nullif(v_validation->>'validatorVersion', ''),
    nullif(v_validation->>'rulesVersion', ''),
    (select auth.uid()),
    (select auth.uid())
  )
  returning id into v_id;

  insert into public.e_document_contents (e_document_id, organisation_id, xml)
  values (v_id, v_org, p_xml);

  insert into public.e_document_validation_results (
    e_document_id, organisation_id, layer, rule_id, severity, location, message
  )
  select
    v_id,
    v_org,
    item->>'layer',
    item->>'ruleId',
    item->>'severity',
    nullif(item->>'location', ''),
    item->>'message'
  from jsonb_array_elements(coalesce(v_validation->'results', '[]'::jsonb)) as item;

  if v_fatal then
    v_status := 'invalid';
  elsif v_direction = 'inbound' then
    select id into v_duplicate
    from public.e_documents
    where organisation_id = v_org
      and direction = 'inbound'
      and id <> v_id
      and status <> 'rejected'
      and ubl_root is not distinct from nullif(v_summary->>'ublRoot', '')
      and document_number is not distinct from nullif(v_summary->>'documentNumber', '')
      and nullif(v_summary->>'documentNumber', '') is not null
      and (
        (
          nullif(sender_id, '') is not null
          and nullif(v_summary->>'senderId', '') is not null
          and sender_scheme is not distinct from nullif(v_summary->>'senderScheme', '')
          and lower(sender_id) is not distinct from lower(v_summary->>'senderId')
        )
        or (
          (nullif(sender_id, '') is null or nullif(v_summary->>'senderId', '') is null)
          and nullif(seller_vat_number, '') is not null
          and lower(seller_vat_number) is not distinct from lower(nullif(v_summary->>'sellerVat', ''))
        )
      )
    order by created_at
    limit 1;
    if v_duplicate is not null then
      v_status := 'duplicate';
    else
      v_status := 'valid';
    end if;
  else
    v_status := 'valid';
  end if;

  perform private.set_e_document_status(
    v_id,
    v_status,
    jsonb_strip_nulls(jsonb_build_object('duplicateOf', v_duplicate))
  );
  return v_id;
end;
$_$;


--
-- Name: void_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_document(p_header_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_org uuid;
  v_status public.document_status;
  v_date date;
  v_direction text;
  v_reason text := nullif(btrim(p_reason), '');
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in before voiding a document';
  end if;
  if v_reason is null or char_length(v_reason) > 500 then
    raise exception 'Enter a reason for voiding this document';
  end if;

  select header.organisation_id, header.status, header.transaction_date, kind.type
    into v_org, v_status, v_date, v_direction
  from public.transaction_headers as header
  join public.transaction_types as kind on kind.id = header.transaction_type_id
  where header.id = p_header_id
  for update of header;

  if v_org is null then
    raise exception 'That document could not be voided';
  end if;
  if v_direction = 'Sales' then
    raise exception 'A posted sales document cannot be voided. Issue a credit note instead.';
  end if;
  if not (select private.has_org_role(v_org, array['owner', 'admin'])) then
    raise exception 'You need an owner or admin role to void a document';
  end if;
  if v_status is distinct from 'posted' then
    raise exception 'Only a posted document can be voided';
  end if;
  if private.document_period_locked(v_org, v_date) then
    raise exception 'This date is in a locked period';
  end if;

  perform set_config('fintran.status_change', 'on', true);
  update public.transaction_headers
  set status = 'void',
      voided_at = now(),
      voided_by = (select auth.uid()),
      void_reason = v_reason
  where id = p_header_id;
  perform set_config('fintran.status_change', 'off', true);
end;
$$;




