    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    updated_by uuid,
    vat_number text,
    address_line1 text,
    address_line2 text,
    address_line3 text,
    city text,
    post_code text,
    county text,
    country_code text DEFAULT 'IE'::text NOT NULL,
    address_needs_review boolean DEFAULT false NOT NULL,
    company_number text,
    peppol_scheme text,
    peppol_id text,
    payment_terms_days integer,
    default_buyer_reference text,
    CONSTRAINT customers_address_line1_check CHECK (((address_line1 IS NULL) OR ((char_length(address_line1) >= 1) AND (char_length(address_line1) <= 100)))),
    CONSTRAINT customers_address_line2_check CHECK (((address_line2 IS NULL) OR ((char_length(address_line2) >= 1) AND (char_length(address_line2) <= 100)))),
    CONSTRAINT customers_address_line3_check CHECK (((address_line3 IS NULL) OR ((char_length(address_line3) >= 1) AND (char_length(address_line3) <= 100)))),
    CONSTRAINT customers_city_check CHECK (((city IS NULL) OR ((char_length(city) >= 1) AND (char_length(city) <= 60)))),
    CONSTRAINT customers_code_check CHECK ((code ~ '^[A-Z0-9][A-Z0-9.-]{0,19}$'::text)),
    CONSTRAINT customers_company_number_check CHECK (((company_number IS NULL) OR (((char_length(company_number) >= 1) AND (char_length(company_number) <= 40)) AND (company_number ~ '^[A-Za-z0-9][A-Za-z0-9 ./-]*$'::text)))),
    CONSTRAINT customers_contact_details_check CHECK (((contact_details IS NULL) OR ((char_length(contact_details) >= 1) AND (char_length(contact_details) <= 500)))),
    CONSTRAINT customers_county_check CHECK (((county IS NULL) OR ((char_length(county) >= 1) AND (char_length(county) <= 60)))),
    CONSTRAINT customers_default_buyer_reference_check CHECK (((default_buyer_reference IS NULL) OR ((char_length(default_buyer_reference) >= 1) AND (char_length(default_buyer_reference) <= 100)))),
    CONSTRAINT customers_email_check CHECK (((email IS NULL) OR ((char_length(email) <= 200) AND (email ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text)))),
    CONSTRAINT customers_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 200))),
    CONSTRAINT customers_notes_check CHECK (((notes IS NULL) OR ((char_length(notes) >= 1) AND (char_length(notes) <= 4000)))),
    CONSTRAINT customers_payment_terms_days_check CHECK (((payment_terms_days IS NULL) OR ((payment_terms_days >= 0) AND (payment_terms_days <= 365)))),
    CONSTRAINT customers_peppol_check CHECK ((((peppol_scheme IS NULL) AND (peppol_id IS NULL)) OR ((peppol_scheme IS NOT NULL) AND (peppol_id IS NOT NULL)))),
    CONSTRAINT customers_peppol_id_check CHECK (((peppol_id IS NULL) OR (peppol_id ~ '^[A-Za-z0-9._:-]{1,100}$'::text))),
    CONSTRAINT customers_phone_check CHECK (((phone IS NULL) OR (((char_length(phone) >= 1) AND (char_length(phone) <= 40)) AND (phone ~ '^[0-9+(). -]+$'::text)))),
    CONSTRAINT customers_post_code_check CHECK (((post_code IS NULL) OR ((char_length(post_code) >= 1) AND (char_length(post_code) <= 20)))),
    CONSTRAINT customers_vat_number_check CHECK (((vat_number IS NULL) OR (vat_number ~ '^[A-Z]{2}[A-Z0-9]{2,13}$'::text))),
    CONSTRAINT customers_website_check CHECK (((website IS NULL) OR (((char_length(website) >= 1) AND (char_length(website) <= 200)) AND (website !~ '[[:space:]]'::text))))
);


