    currency_code text,
    total_amount numeric(18,2),
    amount_due numeric(18,2),
    seller_name text,
    seller_vat_number text,
    buyer_name text,
    buyer_vat_number text,
    semantic jsonb,
    validator_version text,
    rules_version text,
    validated_at timestamp with time zone,
    rejection_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT e_documents_byte_size_check CHECK (((byte_size >= 1) AND (byte_size <= 4194304))),
    CONSTRAINT e_documents_rejection_reason_check CHECK (((status <> 'rejected'::public.e_document_status) OR (NULLIF(btrim(rejection_reason), ''::text) IS NOT NULL))),
    CONSTRAINT e_documents_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT e_documents_source_check CHECK ((source = ANY (ARRAY['generated'::text, 'manual_upload'::text]))),
    CONSTRAINT e_documents_ubl_root_check CHECK ((ubl_root = ANY (ARRAY['Invoice'::text, 'CreditNote'::text]))),
    CONSTRAINT e_documents_validated_check CHECK (((validated_at IS NULL) OR ((validator_version IS NOT NULL) AND (rules_version IS NOT NULL))))
);


