    updated_by uuid,
    status public.document_status DEFAULT 'draft'::public.document_status NOT NULL,
    posted_at timestamp with time zone,
    posted_by uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    issuer_snapshot jsonb,
    party_snapshot jsonb,
    supplier_reference text,
    supply_date date,
    customer_id uuid,
    rounding_amount numeric(18,2) DEFAULT 0 NOT NULL,
    amount_due numeric(18,2) NOT NULL,
    preceding_header_id uuid,
    preceding_reference text,
    preceding_date date,
    buyer_reference text,
    contract_reference text,
    payment_terms text,
    invoice_period_start date,
    invoice_period_end date,
    payment_means_code text,
    document_number text,
    sales_order_reference text,
    closed_by_system boolean DEFAULT false NOT NULL,
    CONSTRAINT transaction_headers_buyer_reference_check CHECK (((buyer_reference IS NULL) OR ((char_length(buyer_reference) >= 1) AND (char_length(buyer_reference) <= 100)))),
    CONSTRAINT transaction_headers_contact_details_check CHECK (((contact_details IS NULL) OR ((char_length(contact_details) >= 1) AND (char_length(contact_details) <= 500)))),
    CONSTRAINT transaction_headers_contract_reference_check CHECK (((contract_reference IS NULL) OR ((char_length(contract_reference) >= 1) AND (char_length(contract_reference) <= 60)))),
    CONSTRAINT transaction_headers_document_number_check CHECK (((document_number IS NULL) OR ((char_length(document_number) >= 1) AND (char_length(document_number) <= 30)))),
    CONSTRAINT transaction_headers_draft_clean CHECK (((status <> 'draft'::public.document_status) OR ((posted_at IS NULL) AND (posted_by IS NULL) AND (issuer_snapshot IS NULL) AND (party_snapshot IS NULL)))),
    CONSTRAINT transaction_headers_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
    CONSTRAINT transaction_headers_flex1_check CHECK (((flex1 IS NULL) OR ((char_length(flex1) >= 1) AND (char_length(flex1) <= 200)))),
    CONSTRAINT transaction_headers_flex2_check CHECK (((flex2 IS NULL) OR ((char_length(flex2) >= 1) AND (char_length(flex2) <= 200)))),
    CONSTRAINT transaction_headers_flex3_check CHECK (((flex3 IS NULL) OR ((char_length(flex3) >= 1) AND (char_length(flex3) <= 200)))),
    CONSTRAINT transaction_headers_flex4_check CHECK (((flex4 IS NULL) OR ((char_length(flex4) >= 1) AND (char_length(flex4) <= 200)))),
    CONSTRAINT transaction_headers_flex5_check CHECK (((flex5 IS NULL) OR ((char_length(flex5) >= 1) AND (char_length(flex5) <= 200)))),
    CONSTRAINT transaction_headers_invoice_period_check CHECK ((((invoice_period_start IS NULL) AND (invoice_period_end IS NULL)) OR ((invoice_period_start IS NOT NULL) AND (invoice_period_end IS NOT NULL) AND (invoice_period_end >= invoice_period_start)))),
    CONSTRAINT transaction_headers_notes_check CHECK (((notes IS NULL) OR ((char_length(notes) >= 1) AND (char_length(notes) <= 4000)))),
    CONSTRAINT transaction_headers_order_number_check CHECK (((order_number IS NULL) OR ((char_length(order_number) >= 1) AND (char_length(order_number) <= 200)))),
    CONSTRAINT transaction_headers_paid_amount_check CHECK ((paid_amount >= (0)::numeric)),
    CONSTRAINT transaction_headers_party_name_check CHECK (((char_length(party_name) >= 1) AND (char_length(party_name) <= 200))),
    CONSTRAINT transaction_headers_payment_terms_check CHECK (((payment_terms IS NULL) OR ((char_length(payment_terms) >= 1) AND (char_length(payment_terms) <= 400)))),
    CONSTRAINT transaction_headers_posted_complete CHECK ((((status)::text <> ALL (ARRAY['posted'::text, 'void'::text])) OR ((document_number IS NOT NULL) AND (issuer_snapshot IS NOT NULL) AND (party_snapshot IS NOT NULL) AND (posted_at IS NOT NULL)))),
    CONSTRAINT transaction_headers_preceding_reference_check CHECK (((preceding_reference IS NULL) OR ((char_length(preceding_reference) >= 1) AND (char_length(preceding_reference) <= 60)))),
    CONSTRAINT transaction_headers_reference_check CHECK (((reference IS NULL) OR (reference > 0))),
    CONSTRAINT transaction_headers_reference_when_posted_check CHECK (((status = 'draft'::public.document_status) OR (reference IS NOT NULL))),
    CONSTRAINT transaction_headers_sales_order_reference_check CHECK (((sales_order_reference IS NULL) OR ((char_length(sales_order_reference) >= 1) AND (char_length(sales_order_reference) <= 200)))),
    CONSTRAINT transaction_headers_supplier_reference_check CHECK (((supplier_reference IS NULL) OR ((char_length(supplier_reference) >= 1) AND (char_length(supplier_reference) <= 60)))),
    CONSTRAINT transaction_headers_void_complete CHECK (((status <> 'void'::public.document_status) OR ((voided_at IS NOT NULL) AND (void_reason IS NOT NULL)))),
    CONSTRAINT transaction_headers_void_only CHECK (((status = 'void'::public.document_status) OR ((voided_at IS NULL) AND (voided_by IS NULL) AND (void_reason IS NULL)))),
    CONSTRAINT transaction_headers_void_reason_check CHECK (((void_reason IS NULL) OR ((char_length(void_reason) >= 1) AND (char_length(void_reason) <= 500))))
);


