    CONSTRAINT transaction_lines_seller_item_id_check CHECK (((seller_item_id IS NULL) OR ((char_length(seller_item_id) >= 1) AND (char_length(seller_item_id) <= 60)))),
    CONSTRAINT transaction_lines_vat_percentage_check CHECK (((vat_percentage >= (0)::numeric) AND (vat_percentage <= (100)::numeric)))
);


