);


--
-- Name: order_line_usage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.order_line_usage WITH (security_invoker='true') AS
 SELECT line.id AS line_id,
    line.header_id,
    line.organisation_id,
    line.quantity,
    (COALESCE(drawn.posted, (0)::numeric) - COALESCE(returned.quantity, (0)::numeric)) AS invoiced,
    COALESCE(drawn.draft, (0)::numeric) AS reserved,
    ((line.quantity - (COALESCE(drawn.posted, (0)::numeric) - COALESCE(returned.quantity, (0)::numeric))) - COALESCE(drawn.draft, (0)::numeric)) AS remaining
   FROM ((((public.transaction_lines line
     JOIN public.transaction_headers header ON ((header.id = line.header_id)))
     JOIN public.transaction_types kind ON ((kind.id = header.transaction_type_id)))
     LEFT JOIN LATERAL ( SELECT sum(taken.quantity) FILTER (WHERE (taken_header.status = 'posted'::public.document_status)) AS posted,
            sum(taken.quantity) FILTER (WHERE (taken_header.status = 'draft'::public.document_status)) AS draft
           FROM (public.transaction_lines taken
             JOIN public.transaction_headers taken_header ON ((taken_header.id = taken.header_id)))
          WHERE (taken.source_line_id = line.id)) drawn ON (true))
     LEFT JOIN LATERAL ( SELECT sum(credit.quantity) AS quantity
           FROM ((public.transaction_lines credit
             JOIN public.transaction_headers credit_header ON ((credit_header.id = credit.header_id)))
             JOIN public.transaction_lines credited ON ((credited.id = credit.credited_line_id)))
          WHERE ((credited.source_line_id = line.id) AND credit.returns_to_order AND (credit_header.status = 'posted'::public.document_status))) returned ON (true))
  WHERE (kind.document_kind = 'order'::public.document_kind);


