    address_needs_review boolean DEFAULT false NOT NULL,
    company_number text,
    peppol_scheme text,
    peppol_id text,
    payment_terms_days integer,
    CONSTRAINT suppliers_address_line1_check CHECK (((address_line1 IS NULL) OR ((char_length(address_line1) >= 1) AND (char_length(address_line1) <= 100)))),
    CONSTRAINT suppliers_address_line2_check CHECK (((address_line2 IS NULL) OR ((char_length(address_line2) >= 1) AND (char_length(address_line2) <= 100)))),
    CONSTRAINT suppliers_address_line3_check CHECK (((address_line3 IS NULL) OR ((char_length(address_line3) >= 1) AND (char_length(address_line3) <= 100)))),
    CONSTRAINT suppliers_city_check CHECK (((city IS NULL) OR ((char_length(city) >= 1) AND (char_length(city) <= 60)))),
    CONSTRAINT suppliers_code_check CHECK ((code ~ '^[A-Z0-9][A-Z0-9.-]{0,19}$'::text)),
    CONSTRAINT suppliers_company_number_check CHECK (((company_number IS NULL) OR (((char_length(company_number) >= 1) AND (char_length(company_number) <= 40)) AND (company_number ~ '^[A-Za-z0-9][A-Za-z0-9 ./-]*$'::text)))),
    CONSTRAINT suppliers_contact_details_check CHECK (((contact_details IS NULL) OR ((char_length(contact_details) >= 1) AND (char_length(contact_details) <= 500)))),
    CONSTRAINT suppliers_county_check CHECK (((county IS NULL) OR ((char_length(county) >= 1) AND (char_length(county) <= 60)))),
    CONSTRAINT suppliers_email_check CHECK (((email IS NULL) OR ((char_length(email) <= 200) AND (email ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text)))),
    CONSTRAINT suppliers_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 200))),
    CONSTRAINT suppliers_notes_check CHECK (((notes IS NULL) OR ((char_length(notes) >= 1) AND (char_length(notes) <= 4000)))),
    CONSTRAINT suppliers_payment_terms_days_check CHECK (((payment_terms_days IS NULL) OR ((payment_terms_days >= 0) AND (payment_terms_days <= 365)))),
    CONSTRAINT suppliers_peppol_check CHECK ((((peppol_scheme IS NULL) AND (peppol_id IS NULL)) OR ((peppol_scheme IS NOT NULL) AND (peppol_id IS NOT NULL)))),
    CONSTRAINT suppliers_peppol_id_check CHECK (((peppol_id IS NULL) OR (peppol_id ~ '^[A-Za-z0-9._:-]{1,100}$'::text))),
    CONSTRAINT suppliers_phone_check CHECK (((phone IS NULL) OR (((char_length(phone) >= 1) AND (char_length(phone) <= 40)) AND (phone ~ '^[0-9+(). -]+$'::text)))),
    CONSTRAINT suppliers_post_code_check CHECK (((post_code IS NULL) OR ((char_length(post_code) >= 1) AND (char_length(post_code) <= 20)))),
    CONSTRAINT suppliers_vat_number_check CHECK (((vat_number IS NULL) OR (vat_number ~ '^[A-Z]{2}[A-Z0-9]{2,13}$'::text))),
    CONSTRAINT suppliers_website_check CHECK (((website IS NULL) OR (((char_length(website) >= 1) AND (char_length(website) <= 200)) AND (website !~ '[[:space:]]'::text))))
);


--
-- Name: tenants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    updated_by uuid,
    CONSTRAINT tenants_name_check CHECK (((char_length(btrim(name)) >= 2) AND (char_length(btrim(name)) <= 80))),
    CONSTRAINT tenants_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text))
);


--
-- Name: transaction_forms; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transaction_forms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    transaction_type_id uuid NOT NULL,
    layout jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    updated_by uuid,
    CONSTRAINT transaction_forms_layout_check CHECK (((jsonb_typeof(layout) = 'object'::text) AND (char_length((layout)::text) <= 8000)))
);


--
-- Name: transaction_vat_breakdown; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transaction_vat_breakdown (
    header_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    vat_category text NOT NULL,
    vat_percentage numeric(5,2) NOT NULL,
    exemption_code text,
    exemption_reason text,
    taxable_amount numeric(18,2) NOT NULL,
    vat_amount numeric(18,2) NOT NULL,
    CONSTRAINT transaction_vat_breakdown_exemption_reason_check CHECK (((exemption_reason IS NULL) OR ((char_length(exemption_reason) >= 1) AND (char_length(exemption_reason) <= 200))))
);


--
-- Name: vat_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vat_rates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    organisation_id uuid NOT NULL,
    code text NOT NULL,
    description text NOT NULL,
    rate numeric(5,2) NOT NULL,
    vat_type text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    updated_by uuid,
    vat_category text NOT NULL,
    exemption_code text,
    exemption_reason text,
    CONSTRAINT vat_rates_code_check CHECK ((code ~ '^[A-Z0-9][A-Z0-9.-]{0,19}$'::text)),
    CONSTRAINT vat_rates_description_check CHECK (((char_length(description) >= 1) AND (char_length(description) <= 200))),
    CONSTRAINT vat_rates_exemption_reason_check CHECK (((exemption_reason IS NULL) OR ((char_length(exemption_reason) >= 1) AND (char_length(exemption_reason) <= 200)))),
    CONSTRAINT vat_rates_rate_check CHECK (((rate >= (0)::numeric) AND (rate <= (100)::numeric))),
    CONSTRAINT vat_rates_vat_type_check CHECK ((vat_type = ANY (ARRAY['Sales'::text, 'Expense'::text])))
);


