-- Name: tenants tenants_select_member; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY tenants_select_member ON public.tenants FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.organisation_access access
  WHERE ((access.tenant_id = tenants.id) AND (access.user_id = ( SELECT auth.uid() AS uid))))));


