-- Comments on tables, columns, functions and views.
COMMENT ON TYPE public.document_kind IS 'invoice is EN 16931 BT-3 380 and credit_note is 381. order is not exported and is left out of later VAT reporting.';
COMMENT ON FUNCTION private.format_document_number(p_prefix text, p_padding integer, p_reference integer) IS 'Prefix plus zero padding. Padding 0 keeps the reference as written, because lpad to width 0 would erase it.';
COMMENT ON COLUMN public.ai_actions.status IS 'proposed until the person decides. confirmed once the token is used and the action ran. failed when it was used and the action did not run. expired after ten minutes. superseded when the same person was given a newer proposal for the same thing.';
COMMENT ON COLUMN public.ai_actions.token_hash IS 'SHA-256 of the confirmation token, in hex. The token itself is never stored.';
COMMENT ON COLUMN public.ai_actions.expires_at IS 'Proposal time plus ten minutes.';
COMMENT ON COLUMN public.ai_actions.target_id IS 'The document being posted, when there is one.';
COMMENT ON COLUMN public.ai_actions.target_version IS 'The target header''s updated_at when it was proposed.';
COMMENT ON COLUMN public.ai_actions.proposal IS 'The summary the server built from the database and showed to the person.';
COMMENT ON COLUMN public.ai_settings.log_answers IS 'When true, a rated answer keeps the question and the answer text with the rating. When false only the rating and comment are kept.';
COMMENT ON COLUMN public.ai_settings.actions_enabled IS 'When true, Ask Qula may propose posting a draft or adding a customer or supplier. It can only be true while enabled is true. Nothing happens until a person confirms.';
COMMENT ON COLUMN public.ai_settings.answer_retention_days IS 'How many days the question, answer and comment kept with a rating are stored, from 1 to 365. After that the text is deleted and the rating is kept.';
COMMENT ON COLUMN public.ai_settings.log_notice_accepted_at IS 'When an owner or admin last accepted the notice that questions and answers will be stored for answer_retention_days and are visible to owners and admins.';
COMMENT ON COLUMN public.ai_settings.log_notice_accepted_by IS 'Who accepted that notice.';
