COMMENT ON COLUMN public.suppliers.vat_number IS 'EN 16931 BT-31 Seller VAT identifier';
COMMENT ON COLUMN public.suppliers.address_line1 IS 'EN 16931 BT-35 Seller address line 1';
COMMENT ON COLUMN public.suppliers.address_line2 IS 'EN 16931 BT-36 Seller address line 2';
COMMENT ON COLUMN public.suppliers.address_line3 IS 'EN 16931 BT-162 Seller address line 3';
COMMENT ON COLUMN public.suppliers.city IS 'EN 16931 BT-37 Seller city';
COMMENT ON COLUMN public.suppliers.post_code IS 'EN 16931 BT-38 Seller post code';
COMMENT ON COLUMN public.suppliers.county IS 'EN 16931 BT-39 Seller country subdivision';
COMMENT ON COLUMN public.suppliers.country_code IS 'EN 16931 BT-40 Seller country code';
COMMENT ON COLUMN public.suppliers.company_number IS 'EN 16931 BT-30 Seller legal registration identifier';
COMMENT ON COLUMN public.suppliers.peppol_scheme IS 'EN 16931 BT-34 Seller electronic address scheme';
COMMENT ON COLUMN public.suppliers.peppol_id IS 'EN 16931 BT-34 Seller electronic address';
COMMENT ON COLUMN public.suppliers.payment_terms_days IS 'Days stored for the supplier. Purchase drafts are not prefilled from it';
COMMENT ON TABLE public.tenants IS 'Deletion is blocked while any transaction header or line exists. Those foreign keys are ON DELETE RESTRICT so a tenant cascade cannot bypass the organisation restrict on documents. Setup rows still cascade. There is no API function for deleting a tenant.';
COMMENT ON TABLE public.transaction_vat_breakdown IS 'EN 16931 BG-23 VAT breakdown. Maintained by the header totals trigger.';
COMMENT ON COLUMN public.transaction_vat_breakdown.vat_category IS 'EN 16931 BT-118 VAT category code';
COMMENT ON COLUMN public.transaction_vat_breakdown.vat_percentage IS 'EN 16931 BT-119 VAT category rate';
COMMENT ON COLUMN public.transaction_vat_breakdown.exemption_code IS 'EN 16931 BT-121 VAT exemption reason code';
COMMENT ON COLUMN public.transaction_vat_breakdown.exemption_reason IS 'EN 16931 BT-120 VAT exemption reason text';
COMMENT ON COLUMN public.transaction_vat_breakdown.taxable_amount IS 'EN 16931 BT-116 VAT category taxable amount';
COMMENT ON COLUMN public.transaction_vat_breakdown.vat_amount IS 'EN 16931 BT-117 VAT category tax amount';
COMMENT ON COLUMN public.vat_rates.vat_category IS 'EN 16931 BT-118 VAT category code';
COMMENT ON COLUMN public.vat_rates.exemption_code IS 'EN 16931 BT-121 VAT exemption reason code';
COMMENT ON COLUMN public.vat_rates.exemption_reason IS 'EN 16931 BT-120 VAT exemption reason text';

-- The sign-up trigger on Supabase's own users table.
drop trigger if exists on_auth_user_created on auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION private.handle_new_user();

-- Storage: the bucket for organisation logos and who may read and write it.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('organisation-logos', 'organisation-logos', 'f', 2097152, '{image/png,image/jpeg,image/webp,image/gif}'::text[]) on conflict (id) do nothing;
create policy organisation_logos_delete on storage.objects for delete to authenticated using (((bucket_id = 'organisation-logos'::text) AND private.organisation_logo_manage(name)));
create policy organisation_logos_insert on storage.objects for insert to authenticated with check (((bucket_id = 'organisation-logos'::text) AND private.organisation_logo_manage(name)));
create policy organisation_logos_select on storage.objects for select to authenticated using (((bucket_id = 'organisation-logos'::text) AND private.organisation_logo_allowed(name)));
create policy organisation_logos_snapshot_insert on storage.objects for insert to authenticated with check (((bucket_id = 'organisation-logos'::text) AND private.organisation_snapshot_allowed(name)));
create policy organisation_logos_update on storage.objects for update to authenticated using (((bucket_id = 'organisation-logos'::text) AND private.organisation_logo_manage(name))) with check (((bucket_id = 'organisation-logos'::text) AND private.organisation_logo_manage(name)));

